#!/usr/bin/env python3
"""create_framework.py - one-command scaffold for the Appium Python test framework.

Creates the complete, runnable project structure (Android + iOS, Appium 2.x,
pytest, Page Object Model) in the current directory (or --target DIR):

    python create_framework.py            # create everything (never overwrites)
    python create_framework.py --force    # overwrite existing files
    python create_framework.py --dry-run  # preview what would be created

Every file below is written with its complete, production-ready content.
After creation:

    pip install -r requirements.txt
    # edit config/android.yaml and config/ios.yaml (device + app paths)
    python run_tests.py --platform android
    python run_tests.py --platform ios

No file is touched when it already exists unless --force is passed, so the
script is safe to run over an existing checkout (e.g. to restore deleted
files after a `git checkout -- .` mishap).
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

# ---------------------------------------------------------------------------
# File manifest: (relative_path, complete_content) for the whole framework.
# ---------------------------------------------------------------------------
FILES = [
    ('.env.example', '# ---------------------------------------------------------------------------\n# Optional environment overrides for the mobile test framework.\n# Copy to `.env` and adjust - every variable here is optional, the YAML files\n# under config/ contain the defaults. Values set here WIN over the YAML\n# defaults, which lets CI inject per-job values without touching config files.\n# ---------------------------------------------------------------------------\n\n# Target platform: android | ios\n# (CLI flag --platform always wins over this variable)\nAPP_PLATFORM=android\n\n# Appium server management ------------------------------------------------\n# Let the framework start/stop the Appium server automatically (true),\n# or attach to an externally managed server (false, same as external: true)?\nAPP_EXTERNAL=false\n\n# Host/port/binary overrides (defaults come from config/settings.yaml)\nAPPIUM_HOST=127.0.0.1\nAPPIUM_PORT=4723\n# Absolute path to the appium binary. Leave empty to search $PATH.\n# Windows example: C:\\Users\\me\\AppData\\Roaming\\npm\\appium.cmd\nAPPIUM_BINARY=\n\n# Device under test --------------------------------------------------------\n# Override the values from config/<platform>.yaml, e.g. in CI where a\n# specific emulator/simulator instance is provisioned per job.\nAPP_DEVICE_NAME=\nAPP_UDID=\n\n# Application under test ----------------------------------------------------\n# Absolute path to the app under test (apk / .app / .app.zip / .ipa).\n# Overrides `app_path` from config/<platform>.yaml. Leave empty to keep the\n# configured path.\nAPP_PATH=\n\n# Logging -------------------------------------------------------------------\nLOG_LEVEL=INFO\n'),
    ('.gitignore', '# Secrets / local overrides\n.env\n\n# Python\n__pycache__/\n*.py[cod]\n*.egg-info/\n.venv/\nvenv/\n\n# Test tooling caches\n.pytest_cache/\n\n# Runtime output (kept out of git; recreated automatically)\nlogs/\nartifacts/\n\n# Local app binaries - never commit large APKs/IPAs\napps/*\n!apps/README.md\n!apps/.gitkeep\n\n# OS / editors\n.DS_Store\n.idea/\n.vscode/\n'),
    ('README.md', '# Appium Python Test Framework (Android + iOS)\n\nA production-ready, pytest-based mobile test automation framework built on\n**Appium 2.x**, the **Appium Python client (5.x/6.x)** and **Selenium 4**,\nsupporting **Android and iOS** from one code base.\n\n```\nPython 3.9+  |  Appium 2.x  |  Appium Python Client 5+/6+  |  pytest 8+\nPage Object Model  |  W3C Actions + mobile: extensions  |  explicit waits  |  YAML/env config\n```\n\nThe sample tests drive the free cross-platform demo app\n**[TheApp](https://github.com/appium-pro/TheApp)** (login screen), so you\ncan run the suite end-to-end without writing an app first.\n\n---\n\n## Table of contents\n\n1. [Architecture overview](#architecture-overview)\n2. [Directory structure](#directory-structure)\n3. [Prerequisites](#prerequisites)\n4. [Step-by-step setup](#step-by-step-setup)\n5. [Configuration - what to change](#configuration---what-to-change)\n6. [Running the tests](#running-the-tests)\n7. [How the Appium server lifecycle works](#how-the-appium-server-lifecycle-works)\n8. [Gestures - usage & platform notes](#gestures---usage--platform-notes)\n9. [Page objects - how to add a screen](#page-objects---how-to-add-a-screen)\n10. [Logs & failure artifacts](#logs--failure-artifacts)\n11. [Troubleshooting](#troubleshooting)\n12. [Recommended next steps](#recommended-next-steps)\n\n---\n\n## Architecture overview\n\n```\n                 ┌────────────────────────────────────────────────┐\n   pytest ──────►│ conftest.py                                    │\n (CLI options,   │  platform resolution, logging, fixtures,       │\n  fixtures,      │  failure-artifact hooks                        │\n  markers)       └───────────────┬────────────────────────────────┘\n                                 │ appium_server fixture / driver fixture\n                 ┌───────────────▼────────────────────────────────┐\n                 │ drivers/                                       │\n                 │  options_builder.py  (YAML → W3C capabilities) │\n                 │  driver_factory.py   (session creation, errors)│\n                 └───────────────┬────────────────────────────────┘\n                                 │\n                 ┌───────────────▼────────────────────────────────┐\n                 │ utils/                                         │\n                 │  appium_server.py   start/stop/reuse/detect    │\n                 │  config_reader.py   YAML + env + CLI merge     │\n                 │  waits.py  gestures.py  logger.py  screenshot  │\n                 └───────────────┬────────────────────────────────┘\n                                 │ driver\n                 ┌───────────────▼────────────────────────────────┐\n                 │ pages/  (Page Object Model)                    │\n                 │  base_page.py  +  screen page classes          │\n                 │  tests call BUSINESS actions, never locators   │\n                 └────────────────────────────────────────────────┘\n```\n\nDesign decisions (and why):\n\n| Decision | Why |\n|---|---|\n| **One test code path for both platforms** | POM keeps app-behaviour logic shared; only *genuinely* platform-specific selectors (e.g. native alerts) branch on the platform - see `pages/login_page.py`. |\n| **Explicit waits everywhere, zero hard sleeps** | `utils/waits.py` wraps `WebDriverWait`/EC and returns the instant a condition is true. Fast, stable, self-documenting timeouts. |\n| **W3C Actions first, `mobile:` shortcuts where they win** | `TouchAction`/`MultiAction` are removed from Appium 2 and the Python client ≥ 4. Every gesture in `utils/gestures.py` uses W3C pointer actions or current `mobile:` commands (verified against the UiAutomator2/XCUITest driver sources). |\n| **Typed capability options** | `UiAutomator2Options`/`XCUITestOptions` (client ≥ 3) replace the removed `desired_capabilities`; the builder enforces the `appium:` prefix rules of W3C/Appium 2. |\n| **Config layering CLI > env > YAML** | Platform YAML files are isolated per platform; CI overrides device/app per job via env vars without touching git-tracked files. |\n| **Session-scoped Appium server, started only when missing** | The suite probes the W3C `/status` endpoint first and reuses any running server; it only stops a server *it* started (see §7). |\n| **Screenshots/page-source on every failure** | A single pytest hook captures artifacts for the whole suite - page classes never need bespoke failure handling. |\n| **Runner script + pure pytest both supported** | `python run_tests.py --platform ios` is sugar over `pytest --platform ios`; CI can use either. |\n\n### Structure notes vs. the "classic" skeleton\n\nThe layout keeps your requested structure and adds only what industry\nframeworks need:\n\n* `drivers/options_builder.py` keeps capability assembly out of the factory\n  (single responsibility, unit-testable).\n* `utils/errors.py` centralises exceptions so helpers never import pytest.\n* `apps/` holds the (git-ignored) binaries under test; `config/` is\n  data-only YAML; runtime output lives in `logs/` + `artifacts/` (git-ignored).\n* `run_tests.py` is an optional ergonomic wrapper - it sets the same env\n  vars `conftest.py` reads, so both entry points behave identically.\n\n---\n\n## Directory structure\n\n```\nappium-python-framework/\n├── config/                  # data-only YAML configuration\n│   ├── settings.yaml        #   Appium server, paths, timeouts, logging\n│   ├── android.yaml         #   Android target (device, app, caps)\n│   ├── ios.yaml             #   iOS target (simulator, app, signing)\n│   └── README.md\n├── drivers/                 # driver creation layer\n│   ├── __init__.py\n│   ├── options_builder.py   #   YAML → typed Appium options (W3C caps)\n│   └── driver_factory.py    #   session creation, health check, rich errors\n├── pages/                   # Page Object Model\n│   ├── __init__.py\n│   ├── base_page.py         #   shared toolbox (find/click/type/wait/gestures/…)\n│   ├── home_page.py         #   TheApp home screen\n│   ├── login_page.py        #   TheApp login screen (+ platform alert locators)\n│   └── secret_page.py       #   TheApp post-login screen\n├── tests/\n│   └── test_login.py        # sample feature tests (valid/invalid/logout)\n├── utils/                   # framework plumbing (no pytest imports)\n│   ├── __init__.py\n│   ├── appium_server.py     #   server start/stop/detect/reuse\n│   ├── config_reader.py     #   CLI/env/YAML resolution\n│   ├── errors.py            #   shared exception types\n│   ├── gestures.py          #   W3C + mobile: gesture library\n│   ├── logger.py            #   structured logging (suite.log)\n│   ├── screenshot.py        #   screenshots + page source capture\n│   └── waits.py             #   explicit-wait helpers\n├── apps/                    # app binaries (git-ignored) + README\n├── conftest.py              # pytest bootstrap & fixtures\n├── pytest.ini\n├── requirements.txt\n├── run_tests.py             # optional convenience runner\n├── .env.example\n├── .gitignore\n└── create_framework.py      # regeneration script (safe, idempotent)\n```\n\n---\n\n## Prerequisites\n\n| Tool | Version | Purpose | Verify with |\n|---|---|---|---|\n| Python | 3.9+ | framework runtime | `python3 --version` |\n| Node.js + npm | 18+ LTS | Appium 2 server (and drivers) | `node --version` |\n| Appium | **2.x** | automation server | `appium --version` |\n| Appium drivers | `uiautomator2` / `xcuitest` | per-platform automation backends | `appium driver list` |\n| Android: JDK | 17 (or 11 with AGP ≥ 7) | Android tooling | `java -version` |\n| Android SDK | latest | emulator/adb/uiautomator | `adb --version` |\n| iOS (macOS only) | Xcode 15+ incl. simulators | XCUITest/WDA builds | `xcodebuild -version` |\n| macOS | 13+ | iOS testing requires macOS | `sw_vers` |\n\n**Important:** Appium is a *server*; the drivers are separate npm packages it\nloads. Appium 2 ships with **no** drivers - install them explicitly\n(§ Setup, step 4).\n\n---\n\n## Step-by-step setup\n\n### 1. Python environment\n\n```bash\ncd appium-python-framework\npython3 -m venv .venv\nsource .venv/bin/activate        # Windows: .venv\\Scripts\\activate\npython -m pip install -U pip\npip install -r requirements.txt\n```\n\nVerify: `python -c "import appium, selenium; print(appium.__version__)"`\n(the client prints its version on import when asked - if the attribute is\nabsent you are on the expected ≥ 5.x line).\n\n### 2. Appium server + drivers\n\n```bash\nnpm install -g appium@2          # Appium 2.x line\nappium --version                 # expect 2.x\nappium driver install uiautomator2   # Android backend\nappium driver install xcuitest       # iOS backend (macOS)\nappium driver list               # both should show "installed"\n```\n\n### 3. Android setup\n\n```bash\n# 1) Android SDK env (add to ~/.zshrc / ~/.bashrc)\nexport ANDROID_HOME=$HOME/Library/Android/sdk        # macOS default\nexport ANDROID_SDK_ROOT=$ANDROID_HOME\nexport PATH=$PATH:$ANDROID_HOME/platform-tools:$ANDROID_HOME/emulator\nsource ~/.zshrc\n\n# 2) Create an emulator (or use Android Studio AVD manager)\navdmanager create avd -n pixel_9 -k "system-images;android-35;google_apis;x86_64" --device "pixel_9"\nemulator -avd pixel_9 &            # or open Android Studio\n\n# 3) Confirm adb sees it and remember its serial\nadb devices                        # -> emulator-5554   device\n```\n\n> Real device: enable *Developer options → USB debugging*, plug it in and\n> use its `adb devices` serial as `udid`/`device_name` in\n> `config/android.yaml`.\n\n### 4. iOS setup (macOS only)\n\n```bash\nxcode-select --install              # if needed\nxcrun simctl list devices available # note the exact name, e.g. "iPhone 15 Pro"\nxcrun simctl boot "iPhone 15 Pro"   # optional: pre-boot the simulator\nopen -a Simulator\n```\n\nAppium builds WebDriverAgent automatically on the first session (can take a\nfew minutes). Real iPhones additionally need `xcode_org_id` +\n`xcode_signing_id` in `config/ios.yaml` and a development profile installed.\n\n### 5. Get the demo app (TheApp)\n\n```bash\ncd apps\ncurl -LO https://github.com/appium-pro/TheApp/releases/download/v1.12.0/TheApp.apk       # Android\ncurl -LO https://github.com/appium-pro/TheApp/releases/download/v1.12.0/TheApp.app.zip   # iOS\n```\n\nOr point `app_path` at **your** app and keep your own package/bundle ids.\n\n### 6. Configure (edit only the values that are yours)\n\nSee the [Configuration](#configuration---what-to-change) section and\n`config/README.md`. Minimal change set: the `device_name`, `app_path` and\npackage/bundle id values - every one of them is marked `CHANGE ME` in the\nYAML with the discovery command right above it.\n\n### 7. First smoke run\n\n```bash\npython run_tests.py --platform android --device-name emulator-5554 -m smoke\n```\n\nExpected: the runner banner (platform, device, server URL), automatic\nAppium server start, session creation, tests, cleanup, and a summary. Then\nrun the full sample suite (below).\n\n---\n\n## Configuration - what to change\n\nValues that MUST be customized for your project (all marked in the YAML):\n\n| Placeholder | Where | Discover yours with | Purpose |\n|---|---|---|---|\n| `YOUR_DEVICE_NAME` | `android.yaml` `device_name` | `adb devices` | adb serial (`emulator-5554`) |\n| `YOUR_APP_PATH` | `android.yaml` `app_path` | `ls apps/` | `.apk` path (or `APP_PATH` env) |\n| `YOUR_APP_PACKAGE` / `YOUR_APP_ACTIVITY` | `android.yaml` | `adb shell pm list packages` / `aapt dump badging app.apk` | launch target when no `app_path` |\n| `YOUR_DEVICE_NAME` | `ios.yaml` `device_name` | `xcrun simctl list devices` | simulator display name |\n| `YOUR_APP_PATH` | `ios.yaml` `app_path` | `ls apps/` | `.app`/`.app.zip`/`.ipa` path |\n| `YOUR_BUNDLE_ID` | `ios.yaml` `bundle_id` | Xcode target settings | installed-app launch |\n| `YOUR_TEAM_ID` (real devices) | `ios.yaml` `xcode_org_id` | developer.apple.com | WDA signing |\n| test accounts | `tests/test_login.py` | your test data | demo creds are TheApp\'s |\n\nEverything else (server management, timeouts, artifact paths, log level)\nalready has sane defaults in `settings.yaml`.\n\n### Environment variables\n\nCopy `.env.example` to `.env` and adjust; all values are optional and only\noverride YAML defaults. The full list with defaults:\n\n| Variable | Default | Meaning |\n|---|---|---|\n| `APP_PLATFORM` | `android` | target platform |\n| `APP_EXTERNAL` | `false` | attach to an externally managed server |\n| `APPIUM_HOST` / `APPIUM_PORT` | `127.0.0.1` / `4723` | server address |\n| `APPIUM_BINARY` | (from `$PATH`) | absolute path to the appium executable |\n| `APP_DEVICE_NAME` | (from YAML) | device/simulator override (CI) |\n| `APP_UDID` | (from YAML) | udid override (CI) |\n| `APP_PATH` | (from YAML) | app-under-test override (CI) |\n| `LOG_LEVEL` | `INFO` | framework log verbosity |\n\n---\n\n## Running the tests\n\n```bash\n# Convenience runner (recommended for humans)\npython run_tests.py                                    # Android, auto server\npython run_tests.py --platform ios                     # iOS\npython run_tests.py --external-server                  # reuse a running server\npython run_tests.py --platform ios -k login -x         # pytest args pass through\n\n# Pure pytest (recommended for CI) - identical behaviour\npytest --platform android\npytest --platform ios\nAPP_PLATFORM=ios pytest tests/ -m "not android"\n\n# Device overrides\npytest --platform android --udid R58M1234567\npytest --platform ios --device-name "iPhone 15 Pro"\n```\n\nBoth entry points read the same config layer; `run_tests.py` only sets the\nenvironment variables for you.\n\n---\n\n## How the Appium server lifecycle works\n\n`utils/appium_server.py` implements the whole lifecycle explicitly:\n\n1. **Detection** - at session start the manager GETs the W3C\n   `/status` endpoint (`http://host:port/status`). A *reachable status\n   endpoint* - not a bare TCP probe - is the definition of "a server is\n   running".\n2. **Start (auto mode)** - nothing answers → the manager resolves the\n   `appium` binary (config, `APPIUM_BINARY`, or `$PATH`) and launches\n   `appium server --address … --port … --log-level info --log-no-colors`,\n   streaming stdout into `logs/appium_server.log`. It then polls `/status`\n   until healthy (default 30 s) and fails with the log tail if the process\n   dies early.\n3. **Reuse** - a server already answering is **never** restarted; the run\n   logs "already running - reusing" and attaches. This also protects you\n   from accidentally spawning a second instance on the same port.\n4. **External mode** (`external: true` / `APP_EXTERNAL=true`) - the manager\n   only *waits for and validates* the external server (Appium Desktop, a CI\n   service, docker-compose, a grid). It never starts or stops it.\n5. **Stop** - at session end the manager terminates the process **only if\n   this run started it** (`started_by_us`). A reused or external server\n   stays up for the next job - exactly what you want in CI.\n6. **Failure reporting** - start/stop/reuse events are logged at INFO;\n   server ERROR/WARN lines are mirrored into the suite log; startup failures\n   embed the server log tail in the exception message.\n\n### Log flow during a run\n\n```\nsession start ──► [conftest] resolve platform/config → prepare dirs → setup logging\n              ──► [appium_server] probe /status ── no ──► spawn server ──► poll /status ──► ready\n              ──► [driver_factory] health check → build options → create session\nper test      ──► [hooks] TEST START log … TEST FINISH log; on failure: screenshot + page source\nsession end   ──► driver.quit() → server.stop() (only if started by us)\n```\n\n---\n\n## Gestures - usage & platform notes\n\nAll gestures live in `utils/gestures.py`; page objects expose thin\ndelegates. Engine: **W3C pointer actions** (uniform across drivers) with\n**native `mobile:` commands** where they are the recommended API. No\ndeprecated TouchAction APIs anywhere.\n\n```python\nfrom utils import gestures  # or use BasePage delegates\n\n# --- taps ---------------------------------------------------------------\ngestures.tap_at(driver, 100, 320)            # raw coordinates (pixels)\ngestures.tap_element(driver, element)        # element centre\ngestures.double_tap_element(driver, element) # native mobile: doubleClickGesture / doubleTap\ngestures.double_tap_at(driver, x, y)         # iOS note: native doubleTap is element-only\n                                             #   -> transparent W3C fallback here\n# --- long press ----------------------------------------------------------\ngestures.long_press(driver, element=el, duration_seconds=1.2)\ngestures.long_press(driver, x=200, y=600, duration_seconds=1.0)\n# Android: mobile: longClickGesture (duration ms; >=500 ms = long click)\n# iOS:     mobile: touchAndHold (duration seconds)\n\n# --- swipe / scroll ------------------------------------------------------\n# Direction = FINGER TRAVEL. swipe_up reveals content further DOWN the page.\ngestures.swipe_up(driver)                    # full screen\ngestures.swipe_between_coordinates(driver, 100, 500, 100, 200, duration_ms=600)\ngestures.swipe_between_elements(driver, src_element, dst_element)\ngestures.scroll(driver, \'up\', element=list_view_element)   # scroll inside a list\npage.scroll_to_element(driver, AppiumBy.ACCESSIBILITY_ID, \'row 42\')  # swipe-until-visible\n# ScrollView speed: duration 700-1000 ms = drag; 100-250 ms = flick feel.\n\n# --- flick / fling -------------------------------------------------------\ngestures.flick_up(driver)                    # fast W3C swipe (both platforms)\ngestures.fling_android(driver, \'up\')         # native velocity fling (Android only)\n\n# --- drag & drop ---------------------------------------------------------\ngestures.drag_and_drop(driver, source_element, target_element,\n                       hold_seconds=1.0, move_duration_ms=800)\n\n# --- pinch / zoom --------------------------------------------------------\ngestures.zoom_in(driver, element=image_element)    # Android pinchOpenGesture,\n                                                   # iOS mobile: pinch scale>1\ngestures.zoom_out(driver)                          # pinchClose / scale<1\n# Fallbacks to W3C two-finger pinches are attempted automatically.\n\n# --- platform commands ---------------------------------------------------\ngestures.back(driver)                       # Android system back (raises on iOS)\ngestures.hide_keyboard(driver)              # safe: no-op when keyboard is hidden\n```\n\nDirection semantics and platform differences worth remembering:\n\n| Gesture | Android (UiAutomator2) | iOS (XCUITest) |\n|---|---|---|\n| tap | W3C click / `mobile: clickGesture` | W3C; `mobile: tap` exists for special cases |\n| double tap | `mobile: doubleClickGesture` (element **or** coords) | `mobile: doubleTap` (**element only**; coords use W3C) |\n| long press | `mobile: longClickGesture`, duration in **ms**, ≥ 500 ms | `mobile: touchAndHold`, duration in **seconds** |\n| swipe w/ coords | `mobile: swipeGesture`/`dragGesture` or W3C | `mobile: dragFromToForDuration` or W3C (this framework uses W3C) |\n| directional swipe | `mobile: swipeGesture {direction}` | `mobile: swipe {direction}` (no coordinates) |\n| fling | `mobile: flingGesture` (velocity) | no native equivalent → `flick_*` W3C |\n| pinch | `mobile: pinchOpenGesture`/`pinchCloseGesture` (`percent`) | `mobile: pinch {scale, velocity}` |\n| back | `driver.back()` | **no system back** - use in-app navigation |\n| hide keyboard | hides via KEYCODE_BACK, only when shown | `strategy=default/pressKey/swipeDown/tapOutside` |\n\n---\n\n## Page objects - how to add a screen\n\n1. **Locators**: prefer accessibility ids - they are identical on both\n   platforms. Use tuples for platform-only strategies\n   (`AppiumBy.ANDROID_UIAUTOMATOR`, `AppiumBy.IOS_PREDICATE`, XPath...).\n2. **Actions, not clicks**: expose business verbs (`login(username, pw)`,\n   `add_item_to_cart(sku)`) that internally wait + act + wait for the next\n   state.\n3. **Navigation returns pages**: `HomePage.navigate_to_login()` returns a\n   ready `LoginPage` - tests read like the user journey.\n4. **Wait for state, not time**: after an action, wait for the *result*\n   screen element (`wait_logged_in_as`), never `sleep`.\n\nExample (mirrors `tests/test_login.py`):\n\n```python\ndef test_valid_credentials_reach_secret_area(self, driver):\n    secret = (HomePage(driver)\n              .navigate_to_login()\n              .login_success("alice", "mypassword"))       # waits internally\n    assert secret.is_logged_in_as("alice")\n```\n\n---\n\n## Logs & failure artifacts\n\n| Path | Content |\n|---|---|\n| `logs/suite.log` | structured framework log: config summary, server lifecycle, driver creation, per-test start/end, element waits, gestures, failures |\n| `logs/appium_server.log` | raw stdout of the Appium server process (the first place to look when a session fails) |\n| `artifacts/screenshots/*.png` | one per failing test: `<test>_<platform>_<timestamp>.png` |\n| `artifacts/page_source/*.xml` | the view hierarchy at failure time (locator debugging gold) |\n\nFailure artifacts are written by a global pytest hook\n(`pytest_runtest_makereport`), so *every* test gets them for free. Page\nclasses can also capture deliberately via `page.take_screenshot()`.\n\nConsole output is human-friendly; the file logs are machine-readable\n`key=value` lines, e.g.:\n\n```\n2026-09-07 20:41:03 | INFO     | driver_factory | Driver created successfully | session_id=1e2f… platform=android desired=emulator-5554\n2026-09-07 20:41:05 | INFO     | conftest       | TEST FINISH | test=test_valid_credentials_reach_secret_area outcome=passed duration_s=4.2\n```\n\n---\n\n## Troubleshooting\n\n| Symptom | Cause & fix |\n|---|---|\n| `The \'appium\' executable was not found on $PATH` | Install Appium (`npm install -g appium@2`) or set `APPIUM_BINARY` to the absolute path (`appium.cmd` on Windows). |\n| `Appium server exited during startup` + log tail | Port already in use by another process (`lsof -i :4723`); or a driver failed to load (check `logs/appium_server.log`). |\n| `External Appium server not reachable` | Your CI/desktop server isn\'t up yet or host/port mismatch. |\n| `... driver uiautomator2 ... not installed` (session creation) | `appium driver install uiautomator2` / `xcuitest`. The error text tells you this. |\n| `Could not create an Android session` | No device connected: `adb devices`; or `device_name`/`udid` mismatch; app path wrong. |\n| iOS session takes minutes / `xcodebuild` errors | First WDA build is slow - be patient once; then check Xcode license (`sudo xcodebuild -license accept`) and simulator runtime availability. |\n| `No Appium server reachable` at driver creation | auto_start disabled and no external server: enable `auto_start` or start one. |\n| Element timeouts that worked in Appium 1 | Bare capabilities (`deviceName:`) are ignored by Appium 2 - this framework always prefixes `appium:`; the options builder does it for you. |\n| Keyboard not hiding | Android only hides when shown (safe guard built in); iOS supports `strategy="swipeDown"`. |\n| Gesture does nothing on iOS lists | iOS needs real inertial scrolling for some ScrollViews; increase `duration_ms` or use `flick_*`. |\n| StaleElementReference in loops | Re-resolve the element each iteration (our scroll helpers do); never cache list items across swipes. |\n\n### Debugging recipe\n\n1. Read `logs/appium_server.log` tail - the server states the real reason a\n   session/capability failed.\n2. Check the failure screenshot + XML page source in `artifacts/`.\n3. Raise verbosity: `LOG_LEVEL=DEBUG pytest --platform android -k your_test`.\n\n---\n\n## Recommended next steps\n\n1. **Point it at your app**: replace the TheApp pages with your screens and\n   move test data (accounts, SKUs) into config/`.env` or a data module.\n2. **CI matrix**: two jobs (Android/iOS) - each sets `APP_PLATFORM`,\n   `APP_DEVICE_NAME`/`APP_UDID` and `APP_PATH`; `APP_EXTERNAL=true` when\n   Appium runs as a service in the pipeline.\n3. **Parallelism**: pytest-xdist with one device per worker\n   (`APP_UDID`/`APP_DEVICE_NAME` per worker via `pytest --dist`), or shard\n   by marker. (The session-scoped fixtures are per-process, which is what\n   xdist needs.)\n4. **Reports**: pytest-html / Allure; wire `pytest_terminal_summary` or a\n   hook to upload `artifacts/` to your CI.\n5. **Hybrid/webview apps**: add a context helper (driver.context switching)\n   following the same POM pattern; capabilities like\n   `appium:chromedriverExecutable` go in `additional_capabilities`.\n6. **App state hygiene**: decide noReset vs fullReset per environment\n   (fast local vs clean CI) via env override instead of editing YAML.\n7. **Version pinning**: pin `appium-python-client`, `selenium` and - in CI -\n   the Appium driver versions (`appium driver install uiautomator2@<ver>`).\n8. **Accessibility checks**: add assertions on the accessibility snapshot to\n   catch a11y regressions alongside functional ones.\n'),
    ('apps/README.md', '# The `apps/` directory is for the application binaries under test\n# (YOUR .apk / .app / .app.zip / .ipa files). They are git-ignored on purpose:\n# binaries do not belong in source control - download/build them in CI.\n\n# Free demo application used by the example tests:\n#   TheApp  -> https://github.com/appium-pro/TheApp/releases\n# Android: TheApp.apk       (app_package: com.appiumpro.the_app)\n# iOS:     TheApp.app.zip   (bundle_id:   com.appiumpro.the_app)\n\n# Example download (choose YOUR platform):\n#   curl -LO https://github.com/appium-pro/TheApp/releases/download/v1.12.0/TheApp.apk\n#   curl -LO https://github.com/appium-pro/TheApp/releases/download/v1.12.0/TheApp.app.zip\n\n# Then point config/android.yaml (app_path: apps/TheApp.apk) or\n# config/ios.yaml (app_path: apps/TheApp.app.zip) at the file.\n'),
    ('config/README.md', '# config/ - what lives here and what you must change\n\n| File | Purpose |\n|---|---|\n| `settings.yaml` | Global, platform-agnostic settings: Appium server address/behaviour, artifact paths, default timeouts, log level. |\n| `android.yaml` | The Android *target*: device, app, package/activity, reset behaviour, extra capabilities. |\n| `ios.yaml` | The iOS *target*: simulator/device, app, bundle id, signing (real devices), extra capabilities. |\n| (no secrets!) | Credentials and per-job values belong in `.env` (see `.env.example`) or CI variables - never commit them. |\n\n## Minimum edits before your first run\n\n1. `config/android.yaml` -> `device_name` (yours from `adb devices`) and\n   `app_path`/`app_package`+`app_activity`.\n2. `config/ios.yaml` -> `device_name` (yours from `xcrun simctl list devices`)\n   and `app_path`/`bundle_id`.\n3. Optionally copy `.env.example` to `.env` for local overrides.\n\n## Precedence (highest wins)\n\n```\npytest/CLI flags  >  environment variables (.env / CI)  >  settings.yaml  >  <platform>.yaml\n```\n\n| Concern | CLI | Env var | YAML |\n|---|---|---|---|\n| Platform | `--platform ios` | `APP_PLATFORM` | `android` default |\n| Server address | - | `APPIUM_HOST` / `APPIUM_PORT` | `appium.host` / `appium.port` |\n| External server | `--external-server` (run_tests) | `APP_EXTERNAL=true` | `appium.external` |\n| Appium binary | - | `APPIUM_BINARY` | `appium.binary` |\n| Device | `--device-name` / `--udid` | `APP_DEVICE_NAME` / `APP_UDID` | `<platform>.device_name` / `udid` |\n| App under test | - | `APP_PATH` | `<platform>.app_path` |\n| Log level | - | `LOG_LEVEL` | `logging.level` |\n'),
    ('config/android.yaml', '# ============================================================================\n# android.yaml - Android target configuration\n# ----------------------------------------------------------------------------\n# !! WHAT YOU MUST CHANGE BEFORE RUNNING !!\n#   1. device_name  -> the id of YOUR emulator (`adb devices`) or real device\n#   2. app_path     -> path to YOUR .apk (or set APP_PATH=... in .env / CI)\n#   3. udid         -> leave "" for emulators; set it for real devices\n# If you already installed the app on the device you may set app_path: "" and\n# Appium will launch the installed app via app_package + app_activity.\n# ============================================================================\n\nplatform_name: Android            # do not change\nautomation_name: UiAutomator2     # Appium 2 driver name (not an "option")\n\n# adb device serial, e.g. "emulator-5554". Get yours with: adb devices\n# An emulator created in Android Studio is usually named Pixel_X_API_Y\n# (display name) but its adb serial is always emulator-XXXX.\ndevice_name: emulator-5554        # CHANGE ME -> YOUR_DEVICE_NAME\n\n# UDID for real devices (uncomment): "R58M1234567" style serial from `adb devices`\n# udid: ""\n\n# Path to the app under test. Relative paths resolve against the framework\n# root; absolute paths are used as-is. Leave "" to launch the app that is\n# already installed on the device (then app_package/app_activity are used).\napp_path: apps/TheApp.apk         # CHANGE ME -> YOUR_APP_PATH\n\n# Package and launch activity of YOUR app. Example values below belong to the\n# TheApp demo application (https://github.com/appium-pro/TheApp).\napp_package: com.appiumpro.the_app   # CHANGE ME -> YOUR_APP_PACKAGE\napp_activity: com.appiumpro.the_app.MainActivity  # CHANGE ME -> YOUR_APP_ACTIVITY\n\n# no_reset: don\'t clear app data / state between sessions (keeps login state,\n# skips permission dialogs on relaunch). Full app reset = reset between tests.\nno_reset: true\nfull_reset: false\n\n# Auto-grant the permissions the app requests at install time (Android 6+).\nauto_grant_permissions: true\n\n# ---------------------------------------------------------------------------\n# Any other Appium capability you need can be added under\n# `additional_capabilities` and is merged verbatim into the session request:\n#\n# additional_capabilities:\n#   appium:appWaitActivity: com.example.app.SplashActivity\n#   appium:newCommandTimeout: 180\n#   appium:unicodeKeyboard: true\n#   appium:resetKeyboard: true\n#   appium:chromedriverExecutable: /path/to/chromedriver   # hybrid apps only\n# ---------------------------------------------------------------------------\nadditional_capabilities: {}\n'),
    ('config/ios.yaml', '# ============================================================================\n# ios.yaml - iOS target configuration\n# ----------------------------------------------------------------------------\n# !! WHAT YOU MUST CHANGE BEFORE RUNNING !!\n#   1. device_name -> the name of YOUR simulator (xcrun simctl list devices)\n#   2. app_path    -> path to YOUR .app/.app.zip (simulator) or .ipa (device)\n#   3. udid        -> leave "" for simulators you want Appium to pick; set it\n#                     when several simulators/real devices are connected\n# For REAL iPhones you additionally need the signing values at the bottom.\n# ============================================================================\n\nplatform_name: iOS               # do not change\nautomation_name: XCUITest        # Appium 2 driver name (not an "option")\n\n# Simulator NAME as shown by: xcrun simctl list devices available\n# Use the exact name + iOS version, e.g. "iPhone 15 Pro" or\n# "iPhone 16 (18.0)" depending on your Xcode version. CHANGE ME.\ndevice_name: iPhone 15 Pro       # CHANGE ME -> YOUR_DEVICE_NAME\n\n# Prefer UDID when set (simulators and devices both have one):\n# xcrun simctl list devices | grep -i booted   (or use Xcode -> Devices)\n# udid: ""\n\n# Path to the app under test. Relative paths resolve against the framework\n# root. For simulators pass the built .app bundle or a .app.zip; for real\n# devices pass a signed .ipa. Leave "" to launch the installed app (then\n# bundle_id is used).\napp_path: apps/TheApp.app.zip    # CHANGE ME -> YOUR_APP_PATH\n\n# Bundle identifier of YOUR app (Xcode -> target -> General -> Bundle Id).\nbundle_id: com.appiumpro.the_app # CHANGE ME -> YOUR_BUNDLE_ID\n\n# no_reset: don\'t clear app state between sessions. full_reset: full wipe.\nno_reset: true\nfull_reset: false\n\n# Dismiss system permission alerts automatically (location, contacts, ...).\nauto_accept_alerts: true\n\n# ---------------------------------------------------------------------------\n# REAL DEVICE signing (uncomment only when testing on physical iPhones):\n# Your Apple developer team id (Xcode -> target -> Signing & Capabilities):\n# xcode_org_id: YOUR_TEAM_ID\n# xcode_signing_id: iPhone Developer\n# If your app is not ad-hoc signed you must also install a development\n# provisioning profile on the device before running.\n#\n# WebDriverAgent port (default: auto-assigned). Change only on conflicts:\n# wda_local_port: 8100\n#\n# Any other Appium capability (merged verbatim):\n# additional_capabilities:\n#   appium:newCommandTimeout: 180\n#   appium:usePrebuiltWDA: true\n# ---------------------------------------------------------------------------\nadditional_capabilities: {}\n'),
    ('config/settings.yaml', '# ============================================================================\n# settings.yaml - global framework settings (platform-agnostic)\n# ----------------------------------------------------------------------------\n# Everything in this file has a sensible default for local development.\n# Precedence (highest wins): command-line flags > environment variables\n# (.env / CI) > this file > platform YAML files (config/android.yaml, ios.yaml)\n# ============================================================================\n\nappium:\n  # Address the Appium server listens on. 127.0.0.1 is fine for local runs;\n  # use 0.0.0.0 when the server runs on a remote CI machine / grid node.\n  host: 127.0.0.1\n\n  # Standard Appium 2.x port.\n  port: 4723\n\n  # Leave empty for Appium 2.x (W3C endpoints live at the server root).\n  # Set to "/wd/hub" only if you run an Appium 1.x server.\n  base_path: ""\n\n  # Absolute path to the `appium` executable. Empty = search $PATH.\n  # Windows note: this is normally `...\\AppData\\Roaming\\npm\\appium.cmd`.\n  binary: ""\n\n  # Server lifecycle behaviour:\n  #  - auto_start: true  -> the suite starts Appium automatically when no\n  #                         server answers on host:port, and stops it again\n  #                         at session end (only if THIS run started it).\n  #  - external: true    -> never start/stop; an external server (CI service,\n  #                         Appium Desktop, docker, remote grid) is expected.\n  #                         auto_start is ignored in that case.\n  auto_start: true\n  external: false\n\n  # How long to wait for the server to become healthy after launch / for an\n  # external server to answer before giving up.\n  start_timeout_seconds: 30\n  stop_timeout_seconds: 10\n\n  # Verbosity of the spawned Appium server process (debug|info|warn|error).\n  # "debug" is very useful when a driver session fails.\n  log_level: info\n\n  # Optional: restrict which drivers Appium loads, e.g. [uiautomator2] or\n  # [uiautomator2, xcuitest]. Empty list = load every installed driver.\n  use_drivers: []\n\npaths:\n  # Relative to the framework root (the directory containing this file\'s\n  # parent). The framework creates these automatically on startup.\n  logs: logs                 # suite log + appium server log\n  screenshots: artifacts/screenshots\n  page_source: artifacts/page_source\n\ntimeouts:\n  # Defaults used by BasePage.wait_for_* and friends. Overridable per call.\n  default: 15                # seconds\n  short: 5\n  long: 30\n\nlogging:\n  # Framework log level: DEBUG | INFO | WARNING | ERROR\n  level: INFO\n  console: true              # mirror logs to stdout\n'),
    ('conftest.py', '"""pytest bootstrap for the mobile framework.\n\nWhat happens here, in order\n---------------------------\n1. ``pytest_addoption``        -> the CLI contract (--platform, --device-name,\n   --udid) so suites run with ``pytest --platform ios`` etc.\n2. ``pytest_configure``        -> resolves the final platform (CLI > env >\n   settings default), loads Settings, prepares log/artifact directories and\n   installs the logging configuration.\n3. ``appium_server`` fixture   -> session-scoped Appium lifecycle. Started\n   only when needed; stopped only if this run started it.\n4. ``driver`` fixture          -> session-scoped driver via DriverFactory;\n   cleaned up reliably afterwards.\n5. pytest hooks                -> test start/end logging and automatic\n   screenshot + page-source capture on failure.\n\nPlatform selection precedence:  ``--platform ios`` > ``APP_PLATFORM=ios``\nenvironment variable > ``android`` default.\n"""\n\nfrom __future__ import annotations\n\nimport os\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent\nif str(ROOT) not in sys.path:\n    sys.path.insert(0, str(ROOT))  # framework root importable from anywhere\n\nimport pytest\n\nfrom drivers.driver_factory import DriverFactory\nfrom utils.appium_server import AppiumServer\nfrom utils.config_reader import Settings, load_settings, resolve_platform\nfrom utils.logger import get_logger, setup_logging\nfrom utils.screenshot import capture_failure_artifacts\n\nLOG = get_logger("conftest")\n\n\n# ---------------------------------------------------------------------------\n# CLI options\n# ---------------------------------------------------------------------------\ndef pytest_addoption(parser: pytest.Parser) -> None:\n    group = parser.getgroup("appium framework")\n    group.addoption(\n        "--platform",\n        action="store",\n        choices=["android", "ios"],\n        default=None,\n        help="Target platform: android or ios (default: APP_PLATFORM env or android)",\n    )\n    group.addoption(\n        "--device-name",\n        action="store",\n        default=None,\n        help="Override the device/simulator name from config/<platform>.yaml",\n    )\n    group.addoption(\n        "--udid",\n        action="store",\n        default=None,\n        help="Override the device UDID from config/<platform>.yaml",\n    )\n\n\n# ---------------------------------------------------------------------------\n# configuration phase\n# ---------------------------------------------------------------------------\ndef pytest_configure(config: pytest.Config) -> None:\n    # 1) Resolve the platform (CLI > APP_PLATFORM > android) and expose it\n    #    through the environment so test modules can read it at import time.\n    platform = resolve_platform(config.getoption("platform"))\n    os.environ["APP_PLATFORM"] = platform\n\n    # 2) CLI device overrides are injected as env vars (highest precedence,\n    #    single code path in config_reader).\n    if config.getoption("device_name"):\n        os.environ["APP_DEVICE_NAME"] = str(config.getoption("device_name"))\n    if config.getoption("udid"):\n        os.environ["APP_UDID"] = str(config.getoption("udid"))\n\n    # 3) Load settings + prepare runtime directories + logging\n    settings = load_settings(platform)\n    settings.log_dir.mkdir(parents=True, exist_ok=True)\n    settings.screenshot_dir.mkdir(parents=True, exist_ok=True)\n    settings.page_source_dir.mkdir(parents=True, exist_ok=True)\n    setup_logging(settings.log_dir, level=settings.log_level, console=True)\n    config._appium_settings = settings  # type: ignore[attr-defined]\n\n    LOG.info("=" * 78)\n    LOG.info("pytest configured for mobile test run")\n    LOG.info("Platform", kv={"platform": platform})\n    LOG.info("Target", kv={"summary": settings.summary()})\n    LOG.info(\n        "Paths",\n        kv={\n            "logs": str(settings.log_dir),\n            "screenshots": str(settings.screenshot_dir),\n            "page_source": str(settings.page_source_dir),\n        },\n    )\n    LOG.info("Appium server", kv={"url": settings.server_url(), "external": settings.external})\n    LOG.info("=" * 78)\n\n\ndef pytest_sessionfinish(session: pytest.Session, exitstatus: int) -> None:\n    settings: Settings = getattr(session.config, "_appium_settings", None)  # type: ignore[attr-defined]\n    if settings is None:\n        return\n    reporter = getattr(session.config, "_terminalreporter", None)\n    counts = {}\n    if reporter is not None:\n        stats = reporter.stats or {}\n        for outcome in ("passed", "failed", "skipped", "error"):\n            counts[outcome] = len(stats.get(outcome, []))\n    LOG.info(\n        "Test session finished",\n        kv={"exitstatus": exitstatus, **counts, "suite_log": str(settings.log_dir / "suite.log")},\n    )\n\n\n# ---------------------------------------------------------------------------\n# fixtures\n# ---------------------------------------------------------------------------\n@pytest.fixture(scope="session")\ndef settings(request: pytest.FixtureRequest) -> Settings:\n    """Resolved runtime settings (platform, device, paths, timeouts...)."""\n    return request.config._appium_settings  # type: ignore[attr-defined]\n\n\n@pytest.fixture(scope="session")\ndef appium_server(request: pytest.FixtureRequest) -> AppiumServer:\n    """Ensure an Appium server is running for the whole session.\n\n    * external mode: verifies the external server answers, never manages it;\n    * auto mode: starts a local server only if none is running; stops it at\n      session end only if this run started it (reused servers stay up).\n    """\n    settings: Settings = request.config._appium_settings  # type: ignore[attr-defined]\n    LOG.info("Appium server fixture: ensuring a server is available")\n    server = AppiumServer(settings)\n    try:\n        server.start()\n    except Exception:\n        LOG.exception("Appium server could not be made available - aborting session")\n        raise\n    yield server\n    server.stop()\n\n\n@pytest.fixture(scope="session")\ndef driver(appium_server: AppiumServer, request: pytest.FixtureRequest):\n    """Session-scoped Appium driver for the configured platform."""\n    settings: Settings = request.config._appium_settings  # type: ignore[attr-defined]\n    factory = DriverFactory(settings)\n    created = factory.create_driver()\n    yield created\n    factory.quit_driver(created)\n\n\n# ---------------------------------------------------------------------------\n# hooks: test logging + failure artifacts\n# ---------------------------------------------------------------------------\ndef pytest_runtest_setup(item: pytest.Item) -> None:\n    LOG.info(\n        "TEST START",\n        kv={\n            "test": item.name,\n            "module": item.module.__name__ if item.module else "?",\n            "platform": os.environ.get("APP_PLATFORM", "?"),\n        },\n    )\n\n\ndef pytest_runtest_makereport(item: pytest.Item, call: pytest.CallInfo) -> None:\n    if call.when != "call":\n        return\n    duration = round(call.duration, 2) if hasattr(call, "duration") else "?"\n    outcome = "passed" if call.excinfo is None else "failed"\n    LOG.info("TEST FINISH", kv={"test": item.name, "outcome": outcome, "duration_s": duration})\n    if call.excinfo is not None:\n        _capture_failure_artifacts(item)\n\n\ndef _capture_failure_artifacts(item: pytest.Item) -> None:\n    """Screenshot + page source after a failure (best effort, never raises)."""\n    try:\n        driver = item.funcargs.get("driver")\n    except Exception:\n        driver = None\n    if driver is None:\n        LOG.debug("No driver available; skipping failure artifacts")\n        return\n    settings: Settings = item.config._appium_settings  # type: ignore[attr-defined]\n    name = f"{item.name}_{os.environ.get(\'APP_PLATFORM\', \'unknown\')}"\n    captured = capture_failure_artifacts(\n        driver,\n        name,\n        screenshot_dir=settings.screenshot_dir,\n        page_source_dir=settings.page_source_dir,\n    )\n    LOG.error("Test failed - failure artifacts saved", kv=captured)\n'),
    ('drivers/__init__.py', '"""Driver layer: platform capability builders and the driver factory.\n\n``drivers/`` has no external dependency on pytest, so the same factory can\nbe reused from CI scripts, one-off device checks or parallel executors.\n"""\n'),
    ('drivers/driver_factory.py', '"""Driver factory: single entry point for creating Android/iOS drivers.\n\n* decides Android vs iOS purely from configuration (never from test code);\n* performs a fast health check against the Appium server *before* a session\n  request, so "server is down" and "session failed" are two distinct,\n  actionable errors;\n* wraps session-creation failures with context-rich messages that point at\n  the real causes (device not connected, driver not installed, app path\n  wrong) - including the Appium server log location.\n"""\n\nfrom __future__ import annotations\n\nimport socket\nfrom typing import Optional\n\nfrom appium import webdriver\nfrom selenium.common.exceptions import WebDriverException\n\nfrom drivers.options_builder import build_options\nfrom utils.appium_server import fetch_status\nfrom utils.config_reader import Settings\nfrom utils.errors import DriverInitializationError\nfrom utils.logger import get_logger\n\nLOG = get_logger("driver_factory")\n\n\nclass DriverFactory:\n    """Creates (and quits) Appium WebDriver sessions from :class:`Settings`."""\n\n    def __init__(self, settings: Settings):\n        self._settings = settings\n\n    # ------------------------------------------------------------------ #\n    @property\n    def settings(self) -> Settings:\n        return self._settings\n\n    def server_url(self) -> str:\n        return self._settings.server_url()\n\n    def check_server(self) -> Optional[dict]:\n        """Return the /status payload when an Appium server is reachable."""\n        return fetch_status(self._settings.health_url(), timeout=2.0)\n\n    # ------------------------------------------------------------------ #\n    def create_driver(self):\n        """Create a session for the configured platform and return the driver.\n\n        Raises:\n            DriverInitializationError: with a diagnostic message when the\n                server is down, the capabilities are invalid, or Appium\n                rejects the session request.\n        """\n        settings = self._settings\n        url = self.server_url()\n\n        LOG.info("Creating driver", kv={"platform": settings.platform, "url": url, "summary": settings.summary()})\n\n        # 1) Fast, explicit server availability check\n        status = self.check_server()\n        if status is None:\n            raise DriverInitializationError(\n                f"No Appium server reachable at {url}. Check that:\\n"\n                f"  * config/settings.yaml points at the right host/port;\\n"\n                f"  * auto_start is enabled or an external server is running;\\n"\n                f"  * the server log {settings.log_dir / \'appium_server.log\'} (if any) shows no errors."\n            )\n        LOG.info("Appium server reachable", kv={"url": url})\n\n        # 2) Build and validate capabilities (fast, local feedback)\n        try:\n            options = build_options(settings)\n        except Exception as exc:\n            raise DriverInitializationError(f"Invalid capabilities: {exc}") from exc\n\n        LOG.debug("Session capabilities", kv={"caps": options.to_capabilities()})\n\n        # 3) Create the session\n        try:\n            driver = webdriver.Remote(url, options=options)\n        except WebDriverException as exc:\n            message = str(exc)\n            hints = self._diagnose_failure(message)\n            raise DriverInitializationError(\n                f"Appium could not create a {settings.platform} session at {url}.\\n"\n                f"Server response: {message[:500]}\\n{hints}"\n            ) from exc\n        except Exception as exc:  # e.g. DNS/connection errors mid-handshake\n            raise DriverInitializationError(\n                f"Unexpected error while creating the {settings.platform} session: {exc}"\n            ) from exc\n\n        LOG.info(\n            "Driver created successfully",\n            kv={\n                "session_id": getattr(driver, "session_id", "?"),\n                "platform": settings.platform,\n                "desired": settings.device.get("device_name"),\n            },\n        )\n        return driver\n\n    # ------------------------------------------------------------------ #\n    def quit_driver(self, driver) -> None:\n        """Safely end a session (never raises)."""\n        if driver is None:\n            return\n        try:\n            driver.quit()\n            LOG.info("Driver session closed")\n        except WebDriverException as exc:\n            LOG.warning("Error while quitting driver (already gone?)", kv={"reason": str(exc)[:200]})\n\n    # ------------------------------------------------------------------ #\n    @staticmethod\n    def _diagnose_failure(message: str) -> str:\n        lowered = (message or "").lower()\n        hints = ["Possible causes and fixes:"]\n        if any(word in lowered for word in ("not installed", "driver", "could not be found", "unknown driver")):\n            hints.append(\n                "  * the Appium driver is not installed - run "\n                "\'appium driver install uiautomator2\' (Android) / "\n                "\'appium driver install xcuitest\' (iOS)"\n            )\n        if "device" in lowered or "emulator" in lowered or "simulator" in lowered:\n            hints.append(\n                "  * no device/emulator/simulator is connected - check "\n                "\'adb devices\' (Android) / \'xcrun simctl list devices\' (iOS)"\n            )\n        if "app" in lowered or "apk" in lowered or "bundle" in lowered:\n            hints.append("  * the app path / package / bundle id may be wrong (config/<platform>.yaml)")\n        if "no such file" in lowered or "file not found" in lowered:\n            hints.append("  * the app binary does not exist on this machine")\n        hints.append("  * full details are in the Appium server log (logs/appium_server.log)")\n        return "\\n".join(hints)\n\n\ndef create_driver(settings: Settings):\n    """Module-level convenience wrapper around :class:`DriverFactory`."""\n    return DriverFactory(settings).create_driver()\n'),
    ('drivers/options_builder.py', '"""Builds Appium 2.x W3C capability objects from the platform YAML files.\n\nWhy an options builder?\n-----------------------\n* Capability keys follow the W3C standard: ``platformName`` is a standard\n  capability; everything Appium-specific is namespaced with the\n  ``appium:`` prefix (``appium:automationName``, ``appium:appPackage``...).\n  Modern Appium *ignores* unprefixed custom capabilities - the builder\n  guarantees the prefixing is always right.\n* ``UiAutomator2Options`` / ``XCUITestOptions`` (the Appium Python client\'s\n  typed option classes) validate and serialize the map; they are the\n  recommended replacement for the removed ``desired_capabilities`` dicts.\n* All validation happens *before* a session request is made, so the error\n  messages point at the exact config value to fix (app path missing,\n  device name missing, ...).\n"""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom appium.options.android import UiAutomator2Options\nfrom appium.options.common.base import AppiumOptions\nfrom appium.options.ios import XCUITestOptions\n\nfrom utils.config_reader import Settings\nfrom utils.errors import ConfigError, DriverInitializationError\n\n# Base capabilities shared by both platforms. ``platformName`` stays\n# unprefixed (W3C); all Appium extension caps carry the ``appium:`` prefix.\ndef _common_capabilities(settings: Settings) -> dict:\n    device = settings.device\n    capabilities = {\n        "platformName": device.get("platform_name"),  # Android / iOS\n        "appium:automationName": device.get("automation_name"),  # UiAutomator2 / XCUITest\n        "appium:deviceName": str(device.get("device_name") or ""),\n    }\n    udid = str(device.get("udid") or "").strip()\n    if udid:\n        capabilities["appium:udid"] = udid\n\n    no_reset = device.get("no_reset", True)\n    full_reset = device.get("full_reset", False)\n    capabilities["appium:noReset"] = bool(no_reset)\n    if full_reset:\n        capabilities["appium:fullReset"] = True\n\n    # App under test: either an explicit path or the already-installed app\n    app_path = settings.resolve_app_path()\n    if app_path:\n        if not Path(app_path).exists():\n            raise ConfigError(\n                f"App binary not found: {app_path}\\n"\n                f"Point app_path in config/{settings.platform}.yaml at YOUR app "\n                f"(or set the APP_PATH environment variable) and try again."\n            )\n        capabilities["appium:app"] = app_path\n    return capabilities\n\n\ndef _platform_capabilities(settings: Settings) -> dict:\n    """Platform-specific capabilities (package/activity vs bundle id)."""\n    device = settings.device\n    capabilities: dict = {}\n    additional = dict(device.get("additional_capabilities") or {})\n\n    if settings.platform == "android":\n        capabilities.update(\n            {\n                "appium:appPackage": str(device.get("app_package") or ""),\n                "appium:appActivity": str(device.get("app_activity") or ""),\n            }\n        )\n        if device.get("auto_grant_permissions", False):\n            capabilities["appium:autoGrantPermissions"] = True\n        if not capabilities.get("appium:app") and not capabilities["appium:appPackage"]:\n            raise ConfigError(\n                "Android config is incomplete: set app_path (a .apk) or "\n                "app_package + app_activity (installed app) in config/android.yaml."\n            )\n    else:  # ios\n        bundle_id = str(device.get("bundle_id") or "")\n        if bundle_id:\n            capabilities["appium:bundleId"] = bundle_id\n        if device.get("auto_accept_alerts", False):\n            capabilities["appium:autoAcceptAlerts"] = True\n        # Real-device signing (optional, only meaningful on physical iPhones)\n        for key in ("xcodeOrgId", "xcodeSigningId"):\n            value = device.get(key) or device.get(key[0].lower() + key[1:])\n            if value:\n                capabilities[f"appium:{key}"] = str(value)\n        if not capabilities.get("appium:app") and not bundle_id:\n            raise ConfigError(\n                "iOS config is incomplete: set app_path (a .app/.zip/.ipa) or "\n                "bundle_id (installed app) in config/ios.yaml."\n            )\n\n    # User-defined extras win over the defaults above\n    capabilities.update(additional)\n    return capabilities\n\n\ndef _validate_device(settings: Settings) -> None:\n    """A device must be addressable: by name, by udid, or (Android) the\n    default emulator serial."""\n    device = settings.device\n    has_name = bool(str(device.get("device_name") or "").strip())\n    has_udid = bool(str(device.get("udid") or "").strip())\n    if settings.platform == "ios" and not has_name and not has_udid:\n        raise ConfigError(\n            "iOS config needs a device: set device_name (simulator name) or "\n            "udid in config/ios.yaml."\n        )\n    if settings.platform == "android" and not has_name and not has_udid:\n        raise ConfigError(\n            "Android config needs a device: set device_name (adb serial, e.g. "\n            "\'emulator-5554\') or udid in config/android.yaml."\n        )\n\n\ndef build_options(settings: Settings) -> AppiumOptions:\n    """Return the typed options object for the configured platform."""\n    _validate_device(settings)\n    capabilities = _common_capabilities(settings)\n    capabilities.update(_platform_capabilities(settings))\n\n    if settings.platform == "android":\n        return UiAutomator2Options().load_capabilities(capabilities)\n    return XCUITestOptions().load_capabilities(capabilities)\n\n\ndef describe_capabilities(settings: Settings) -> dict:\n    """Human-readable capability summary for logs (paths shortened)."""\n    options = build_options(settings)\n    caps = options.to_capabilities()\n    return {key: value for key, value in caps.items() if value not in ("", None)}\n\n\n# Re-export so factory/tests import one name:\nclass CapabilityBuilderError(DriverInitializationError):  # backward-compat alias\n    pass\n'),
    ('pages/__init__.py', '"""Page Object Model.\n\nEach screen of the application under test is one page class that exposes\nbusiness-level actions (``login(username, password)``) and hides locators\nand wait logic. ``BasePage`` provides the shared toolbox.\n"""\n'),
    ('pages/base_page.py', '"""BasePage: the toolbox every page object inherits.\n\nImplements the shared, driver-level actions the framework promises:\n\n* find / click / enter text / read text\n* explicit waits (visible, gone, clickable, text)\n* visibility checks (non-blocking)\n* gestures (swipe/scroll delegates into :mod:`utils.gestures`)\n* screenshots\n\nConventions\n-----------\n* **Locators** are either a plain string (interpreted as an\n  *accessibility id* - the most robust locator on both Android and iOS) or a\n  ``(AppiumBy.X, value)`` tuple for anything else:\n\n  .. code-block:: python\n\n      element = self.find_element("login_btn")                      # by accessibility id\n      element = self.find_element(AppiumBy.XPATH, "//android.widget.Button[@text=\'OK\']")\n      element = self.find_element(AppiumBy.IOS_PREDICATE, "label BEGINSWITH \'Log\'")\n\n* Page methods **wait before they act** (explicit waits, never sleep).\n* Anything that can fail with a timeout produces a\n  :class:`~utils.errors.WaitTimeoutError`; the global pytest hook saves a\n  screenshot + page source automatically on failure.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Any, Optional, Tuple, Union\n\nfrom appium.webdriver.common.appiumby import AppiumBy\nfrom selenium.webdriver.remote.webelement import WebElement\n\nimport utils.gestures as gestures\nimport utils.waits as waits\nfrom utils.config_reader import PROJECT_ROOT, Settings\nfrom utils.logger import get_logger\nfrom utils.screenshot import save_page_source, save_screenshot\n\nLocator = Union[str, Tuple[Any, str]]\n\n\nclass BasePage:\n    """Shared page-object base class.\n\n    Args:\n        driver: the active Appium driver (from the ``driver`` fixture).\n        settings: optional resolved settings (used for artifact paths and\n            default timeouts). Tests can simply pass ``driver``; the\n            defaults match ``config/settings.yaml``.\n    """\n\n    def __init__(self, driver, settings: Optional[Settings] = None):\n        self.driver = driver\n        self.settings = settings\n        self.log = get_logger(f"pages.{type(self).__name__}")\n\n        if settings is not None:\n            self._screenshot_dir = settings.screenshot_dir\n            self._page_source_dir = settings.page_source_dir\n            self._default_timeout = settings.timeout_default\n        else:\n            self._screenshot_dir = PROJECT_ROOT / "artifacts" / "screenshots"\n            self._page_source_dir = PROJECT_ROOT / "artifacts" / "page_source"\n            self._default_timeout = 15\n\n        self.platform = gestures.detect_platform(driver)\n\n    # ------------------------------------------------------------------ #\n    # locator helpers\n    # ------------------------------------------------------------------ #\n    @staticmethod\n    def _to_locator(by: Locator, value=None) -> tuple:\n        if value is None:\n            if isinstance(by, (tuple, list)) and len(by) == 2:\n                return tuple(by)\n            return (AppiumBy.ACCESSIBILITY_ID, by)  # plain string => accessibility id\n        return (by, value)\n\n    def _timeout(self, timeout: Optional[float]) -> float:\n        return self._default_timeout if timeout is None else timeout\n\n    # ------------------------------------------------------------------ #\n    # finding & waiting\n    # ------------------------------------------------------------------ #\n    def find_element(self, by: Locator, value=None, timeout: Optional[float] = None) -> WebElement:\n        """Wait for the element to exist, then return it (no visibility req.)."""\n        return waits.wait_for_presence(\n            self.driver, *self._to_locator(by, value), timeout=self._timeout(timeout)\n        )\n\n    def wait_for_element(self, by: Locator, value=None, timeout: Optional[float] = None) -> WebElement:\n        """Wait until the element is visible and return it (recommended)."""\n        return waits.wait_for_visibility(\n            self.driver, *self._to_locator(by, value), timeout=self._timeout(timeout)\n        )\n\n    def wait_until_gone(self, by: Locator, value=None, timeout: Optional[float] = None) -> bool:\n        """Wait until the element disappears (splash, spinner, dialog)."""\n        return waits.wait_for_invisibility(\n            self.driver, *self._to_locator(by, value), timeout=self._timeout(timeout)\n        )\n\n    def wait_for_text(self, by: Locator, expected_text: str, value=None, timeout: Optional[float] = None) -> bool:\n        """Wait until the element\'s text contains ``expected_text``."""\n        return waits.wait_for_text(\n            self.driver, *self._to_locator(by, value), expected_text, timeout=self._timeout(timeout)\n        )\n\n    def is_visible(self, by: Locator, value=None) -> bool:\n        """Non-blocking check: does the element exist AND is it displayed?"""\n        return waits.is_element_visible(self.driver, *self._to_locator(by, value))\n\n    def is_present(self, by: Locator, value=None) -> bool:\n        """Non-blocking check: does the element exist at all?"""\n        return waits.is_element_present(self.driver, *self._to_locator(by, value))\n\n    # ------------------------------------------------------------------ #\n    # actions\n    # ------------------------------------------------------------------ #\n    def click_element(self, element: WebElement) -> None:\n        """Click an already-resolved element (waits for clickability first)."""\n        waits.wait_for_clickable(\n            self.driver, (AppiumBy.ID, element.id), timeout=self._timeout(None)\n        )\n        element.click()\n        self.log.debug("Clicked element", kv={"element_id": element.id})\n\n    def click(self, by: Locator, value=None, timeout: Optional[float] = None) -> None:\n        """Find (visible) and click. The workhorse of page objects."""\n        locator = self._to_locator(by, value)\n        element = waits.wait_for_clickable(self.driver, *locator, timeout=self._timeout(timeout))\n        element.click()\n        self.log.debug("Clicked element", kv={"locator": (locator[0], str(locator[1]))})\n\n    def tap(self, by: Locator, value=None, timeout: Optional[float] = None) -> None:\n        """Tap the centre of an element via a W3C pointer gesture.\n\n        Prefer ``click()`` for regular buttons; use ``tap()`` when the\n        native click does not register (known iOS quirks with certain\n        custom views).\n        """\n        element = self.wait_for_element(by, value, timeout=timeout)\n        gestures.tap_element(self.driver, element)\n\n    def type_text(\n        self,\n        by: Locator,\n        text: str,\n        value=None,\n        clear_first: bool = True,\n        timeout: Optional[float] = None,\n    ) -> None:\n        """Tap the field, optionally clear it, then type ``text``.\n\n        The element is located by an explicit visibility wait; the typing\n        itself uses native ``send_keys``.\n        """\n        element = self.wait_for_element(by, value, timeout=timeout)\n        self.type_text_element(element, text, clear_first=clear_first)\n\n    def type_text_element(self, element: WebElement, text: str, clear_first: bool = True) -> None:\n        element.click()  # focus the field (shows the keyboard when needed)\n        if clear_first:\n            try:\n                element.clear()\n            except Exception:\n                # Some custom views have no native clear - select-all + delete\n                self.log.debug("element.clear() not supported; skipping")\n        element.send_keys(text)\n        self.log.debug("Entered text", kv={"characters": len(text), "element_id": element.id})\n\n    def clear_text(self, by: Locator, value=None, timeout: Optional[float] = None) -> None:\n        element = self.wait_for_element(by, value, timeout=timeout)\n        element.clear()\n        self.log.debug("Cleared element", kv={"element_id": element.id})\n\n    def get_text(self, by: Locator, value=None, timeout: Optional[float] = None) -> str:\n        """Return the visible text of an element (falls back to its label)."""\n        element = self.wait_for_element(by, value, timeout=timeout)\n        text = element.text\n        if not text:\n            text = element.get_attribute("label") or element.get_attribute("name") or ""\n        self.log.debug("Read text", kv={"characters": len(text)})\n        return text.strip()\n\n    def get_text_element(self, element: WebElement) -> str:\n        text = element.text\n        if not text:\n            text = element.get_attribute("label") or ""\n        return text.strip()\n\n    # ------------------------------------------------------------------ #\n    # gestures (thin delegates into utils.gestures)\n    # ------------------------------------------------------------------ #\n    def swipe(self, direction: str, element: Optional[WebElement] = None, **kwargs) -> None:\n        gestures.scroll(self.driver, direction, element=element, **kwargs)\n\n    def scroll_down(self, element: Optional[WebElement] = None, **kwargs) -> None:\n        """Reveal content further down the page (finger travels up)."""\n        gestures.scroll_up(self.driver, element=element, **kwargs)\n\n    def scroll_up(self, element: Optional[WebElement] = None, **kwargs) -> None:\n        """Reveal content further up the page (finger travels down)."""\n        gestures.scroll_down(self.driver, element=element, **kwargs)\n\n    def scroll_to_element(\n        self,\n        by: Locator,\n        value=None,\n        direction: str = "up",\n        max_swipes: int = 10,\n        container: Optional[WebElement] = None,\n    ) -> WebElement:\n        """Repeatedly swipe until ``by/value`` is visible; then return it."""\n        locator = self._to_locator(by, value)\n        return gestures.scroll_to_element(\n            self.driver,\n            locator[0],\n            locator[1],\n            direction=direction,\n            max_swipes=max_swipes,\n            container=container,\n        )\n\n    def hide_keyboard(self, strategy: Optional[str] = None) -> None:\n        """Hide the soft keyboard if visible (safe on both platforms)."""\n        gestures.hide_keyboard(self.driver, strategy=strategy)\n\n    def back(self) -> None:\n        """Android system back. On iOS raise (apps use in-app navigation)."""\n        gestures.back(self.driver)\n\n    def long_press(self, by: Locator, value=None, duration_seconds: float = 1.0) -> None:\n        element = self.wait_for_element(by, value)\n        gestures.long_press(self.driver, element=element, duration_seconds=duration_seconds)\n\n    def drag_and_drop(\n        self,\n        source: Locator,\n        target: Locator,\n        hold_seconds: float = 1.0,\n        value=None,\n        target_value=None,\n    ) -> None:\n        source_element = self.wait_for_element(source, value)\n        target_element = self.wait_for_element(target, target_value)\n        gestures.drag_and_drop(self.driver, source_element, target_element, hold_seconds=hold_seconds)\n\n    # ------------------------------------------------------------------ #\n    # artifacts & debug\n    # ------------------------------------------------------------------ #\n    def take_screenshot(self, name: Optional[str] = None) -> Any:\n        """Save a screenshot; returns the file path. Used for deliberate\n        captures (e.g. end of smoke tests) - failures are handled globally."""\n        label = name or f"{type(self).__name__}"\n        return save_screenshot(self.driver, self._screenshot_dir, label)\n\n    def dump_page_source(self, name: Optional[str] = None) -> Any:\n        label = name or f"{type(self).__name__}"\n        return save_page_source(self.driver, self._page_source_dir, label)\n\n    def log_tree(self, message: str = "Page state") -> None:\n        """Helper for debugging: log a short summary of the visible view."""\n        source = self.driver.page_source\n        self.log.info(message, kv={"page_source_characters": len(source or "")})\n'),
    ('pages/home_page.py', '"""TheApp home screen page object.\n\nTheApp (https://github.com/appium-pro/TheApp) is the free demo application\nused by the sample tests: it is cross-platform and exposes stable\naccessibility ids. Swap these locators for YOUR app\'s screens.\n"""\n\nfrom __future__ import annotations\n\nfrom pages.base_page import BasePage\n\n\nclass HomePage(BasePage):\n    """The launch screen: a list of available demo screens."""\n\n    # -- locators ------------------------------------------------------- #\n    LOGIN_SCREEN_ROW = "Login Screen"\n    ECHO_BOX_ROW = "Echo Box"\n    LIST_DEMO_ROW = "List Demo"\n\n    # -- actions -------------------------------------------------------- #\n    def navigate_to_login(self) -> "LoginPage":\n        """Open the Login screen and wait until it is ready."""\n        from pages.login_page import LoginPage  # local import avoids cycles\n\n        self.log.info("Navigating to the Login screen")\n        self.wait_for_element(self.LOGIN_SCREEN_ROW)\n        self.click(self.LOGIN_SCREEN_ROW)\n        login_page = LoginPage(self.driver, self.settings)\n        login_page.wait_for_element(LoginPage.USERNAME_FIELD)  # screen ready\n        return login_page\n'),
    ('pages/login_page.py', '"""TheApp Login screen page object (demonstrates the POM pattern).\n\nThe selectors below are the accessibility ids exposed by TheApp\'s login\nscreen (``username``, ``password``, ``loginBtn`` - the app maps both\n``testID`` and ``accessibilityLabel`` to those values).\n\nThe invalid-credentials alert shows how *genuinely platform-specific*\nselectors are handled: both platforms display a native alert, but it can\nonly be queried via platform locators (Android ``resource-id`` XPath vs\niOS NSPredicate).\n"""\n\nfrom __future__ import annotations\n\nfrom appium.webdriver.common.appiumby import AppiumBy\n\nfrom pages.base_page import BasePage\n\n\nclass LoginPage(BasePage):\n    """Login form: two text fields and a Login button."""\n\n    # -- shared locators (accessibility ids, both platforms) ----------- #\n    USERNAME_FIELD = "username"\n    PASSWORD_FIELD = "password"\n    LOGIN_BUTTON = "loginBtn"\n\n    # -- platform-specific alert locators (native alerts differ) ------- #\n    ALERT_TEXT_LOCATORS = {\n        "android": (AppiumBy.XPATH, "//android.widget.TextView[@resource-id=\'android:id/message\']"),\n        "ios": (AppiumBy.IOS_PREDICATE, "label CONTAINS \'Invalid login credentials\'"),\n    }\n    ALERT_OK_BUTTON_LOCATORS = {\n        "android": (AppiumBy.XPATH, "//android.widget.Button[@resource-id=\'android:id/button1\']"),\n        "ios": (AppiumBy.IOS_PREDICATE, "type == \'XCUIElementTypeButton\' AND label == \'OK\'"),\n    }\n\n    # -- low-level actions ---------------------------------------------- #\n    def enter_username(self, username: str) -> "LoginPage":\n        self.type_text(self.USERNAME_FIELD, username)\n        return self\n\n    def enter_password(self, password: str) -> "LoginPage":\n        self.type_text(self.PASSWORD_FIELD, password)\n        return self\n\n    def tap_login(self) -> "LoginPage":\n        # The soft keyboard can cover the Login button on small screens:\n        # hide it first (no-op when it is not shown).\n        self.hide_keyboard()\n        self.click(self.LOGIN_BUTTON)\n        return self\n\n    # -- business-level actions ----------------------------------------- #\n    def login_success(self, username: str, password: str) -> "SecretPage":\n        """Log in with valid credentials and wait for the Secret screen."""\n        from pages.secret_page import SecretPage  # local import avoids cycles\n\n        self.log.info("Logging in (valid credentials)", kv={"username": username})\n        self.enter_username(username).enter_password(password).tap_login()\n        secret_page = SecretPage(self.driver, self.settings)\n        secret_page.wait_logged_in_as(username)\n        return secret_page\n\n    def login_invalid(self, username: str, password: str) -> str:\n        """Log in with invalid credentials; return the alert message text.\n\n        The alert is left open - call :meth:`dismiss_alert` afterwards.\n        """\n        self.log.info("Logging in (invalid credentials)", kv={"username": username})\n        self.enter_username(username).enter_password(password).tap_login()\n        by, value = self.ALERT_TEXT_LOCATORS[self.platform]\n        alert_element = self.wait_for_element((by, value))\n        message = self.get_text_element(alert_element)\n        self.log.info("Invalid-credentials alert shown", kv={"message": message})\n        return message\n\n    def dismiss_alert(self) -> "LoginPage":\n        """Tap the alert\'s OK button (platform-aware)."""\n        by, value = self.ALERT_OK_BUTTON_LOCATORS[self.platform]\n        self.wait_for_element((by, value)).click()\n        return self\n'),
    ('pages/secret_page.py', '"""TheApp "Secret Area" screen page object (shown after a successful login).\n\nThe logged-in username is rendered inside an element whose accessibility id\nis ``Logged in as <username>`` - a useful pattern for assertions.\n"""\n\nfrom __future__ import annotations\n\nfrom appium.webdriver.common.appiumby import AppiumBy\n\nfrom pages.base_page import BasePage\n\n\nclass SecretPage(BasePage):\n    """Post-login screen (only reachable with valid credentials)."""\n\n    # Platform-specific locator for the Logout button: this button has no\n    # accessibility id in TheApp, so we fall back to platform selectors.\n    LOGOUT_BUTTON_LOCATORS = {\n        "android": (AppiumBy.ANDROID_UIAUTOMATOR, \'new UiSelector().text("Logout")\'),\n        "ios": (AppiumBy.IOS_PREDICATE, "name == \'Logout\'"),\n    }\n\n    # ------------------------------------------------------------------ #\n    def logged_in_as_element(self, username: str):\n        """The element whose accessibility id proves the login state."""\n        return self.wait_for_element(f"Logged in as {username}")\n\n    def wait_logged_in_as(self, username: str):\n        """Block until the Secret screen shows the given user."""\n        self.wait_for_element(f"Logged in as {username}")\n        self.log.info("Confirmed logged-in state", kv={"username": username})\n        return self\n\n    def is_logged_in_as(self, username: str) -> bool:\n        """Quick, non-blocking check of the logged-in state."""\n        return self.is_visible(f"Logged in as {username}")\n\n    # ------------------------------------------------------------------ #\n    def logout(self) -> "LoginPage":\n        """Tap Logout and return to the Login screen."""\n        from pages.login_page import LoginPage  # local import avoids cycles\n\n        by, value = self.LOGOUT_BUTTON_LOCATORS[self.platform]\n        self.wait_for_element((by, value)).click()\n        login_page = LoginPage(self.driver, self.settings)\n        login_page.wait_for_element(LoginPage.USERNAME_FIELD)\n        return login_page\n'),
    ('pytest.ini', "[pytest]\nminversion = 8.2\ntestpaths = tests\n\n# -ra            : show a summary of all outcomes (esp. reasons for skips)\n# --strict-markers : typos in markers fail fast instead of silently passing\naddopts = -ra --strict-markers -p no:cacheprovider\n\nmarkers =\n    android: test that only makes sense on Android (e.g. system back button)\n    ios: test that only makes sense on iOS\n    smoke: fast sanity checks; useful for a quick device/tooling smoke run\n    login: TheApp login screen feature tests\n\n# The framework logs to logs/ (see utils/logger.py) - keep pytest's own\n# console output free of log noise:\nlog_cli = false\n"),
    ('requirements.txt', "# Core automation stack -------------------------------------------------------\n# Appium Python client (v5+/v6 uses Selenium 4.26+ under the hood and speaks\n# the W3C protocol. TouchAction/MultiAction were removed in v4 - this framework\n# therefore uses W3C Actions + mobile: extensions exclusively.)\nappium-python-client>=5.1,<7\n\n# Selenium WebDriver bindings (pinned <5 to match the Appium client's matrix).\nselenium>=4.26,<5\n\n# Test runner\npytest>=8.2,<10\n\n# Configuration\nPyYAML>=6.0\npython-dotenv>=1.0\n\n# HTTP calls for the Appium server health checks (utils/appium_server.py)\nrequests>=2.31\n"),
    ('run_tests.py', '#!/usr/bin/env python3\n"""run_tests.py - one-command test runner for the mobile framework.\n\nUsage\n-----\n    python run_tests.py                          # android, auto Appium server\n    python run_tests.py --platform ios           # iOS\n    python run_tests.py --external-server        # attach to a running server\n    python run_tests.py --platform android -k login -x   # pytest args pass through\n\nEverything after the runner\'s own options is forwarded to pytest, so the\nfull pytest CLI (``-k``, ``-m``, ``-x``, ``--html=report.html`` ...) keeps\nworking. The equivalent pure-pytest invocation is:\n\n    APP_PLATFORM=ios pytest tests/\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport os\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent\nsys.path.insert(0, str(ROOT))\n\nfrom utils.config_reader import load_settings  # noqa: E402\nfrom utils.logger import get_logger, setup_logging  # noqa: E402\n\nLOG = get_logger("run_tests")\n\nRUNNER_OPTIONS = ("--platform", "--external-server", "--device-name", "--udid")\n\n\ndef _parse_runner_args(argv: list[str]):\n    """Split argv into (runner options, pytest args). pytest args pass through."""\n    parser = argparse.ArgumentParser(description=__doc__, add_help=False)\n    parser.add_argument("--platform", choices=["android", "ios"], default=None)\n    parser.add_argument("--external-server", action="store_true", help="Attach to an externally managed Appium server")\n    parser.add_argument("--device-name", default=None)\n    parser.add_argument("--udid", default=None)\n    namespace, rest = parser.parse_known_args(argv)\n    return namespace, rest\n\n\ndef _banner(platform: str) -> None:\n    """Resolve settings and print a short, useful summary before running."""\n    settings = load_settings(platform)\n    setup_logging(settings.log_dir, level=settings.log_level, console=True)\n    LOG.info("=" * 78)\n    LOG.info("Mobile test run")\n    LOG.info("Target", kv={"summary": settings.summary()})\n    LOG.info("Appium server", kv={"url": settings.server_url(), "external": settings.external})\n    LOG.info(\n        "Artifacts",\n        kv={\n            "suite_log": str(settings.log_dir / "suite.log"),\n            "screenshots": str(settings.screenshot_dir),\n        },\n    )\n    LOG.info("=" * 78)\n    print(f"\\nRunning {platform} tests with pytest...\\n")\n\n\ndef main(argv: list[str] | None = None) -> int:\n    argv = list(sys.argv[1:] if argv is None else argv)\n    namespace, pytest_args = _parse_runner_args(argv)\n\n    # Runner options become environment variables (highest precedence) so the\n    # pytest run and the banner agree on every value.\n    platform = namespace.platform or os.environ.get("APP_PLATFORM", "android")\n    os.environ["APP_PLATFORM"] = platform\n    if namespace.external_server:\n        os.environ["APP_EXTERNAL"] = "true"\n    if namespace.device_name:\n        os.environ["APP_DEVICE_NAME"] = namespace.device_name\n    if namespace.udid:\n        os.environ["APP_UDID"] = namespace.udid\n\n    _banner(platform)\n\n    command = [sys.executable, "-m", "pytest", str(ROOT / "tests"), *pytest_args]\n    LOG.info("Executing", kv={"command": " ".join(command)})\n    try:\n        result = subprocess.run(command, cwd=str(ROOT))\n    except KeyboardInterrupt:\n        print("\\nInterrupted by user.")\n        return 130\n    return int(result.returncode)\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'),
    ('tests/test_login.py', '"""Sample tests: TheApp login flow (Android + iOS).\n\nTheApp (https://github.com/appium-pro/TheApp) is a free cross-platform test\napplication. Its login screen accepts the demo credentials below and shows\na "Secret Area" screen after a successful login.\n\nREPLACE BEFORE USE IN YOUR PROJECT\n----------------------------------\n* swap ``HomePage``/``LoginPage``/``SecretPage`` usage for YOUR pages;\n* the demo credentials belong to TheApp only - manage your own test\n  accounts in config or an env file;\n* nothing here is platform-specific: the same test runs against Android\n  and iOS via ``--platform`` / ``APP_PLATFORM``.\n\nPlatform gating (when you DO need it) looks like::\n\n    import os\n    needs_android = pytest.mark.skipif(\n        os.environ.get("APP_PLATFORM") != "android", reason="Android only")\n"""\n\nfrom __future__ import annotations\n\nimport pytest\n\nfrom pages.home_page import HomePage\n\n# Demo accounts baked into TheApp (replace with your own test data source):\nVALID_USERNAME = "alice"      # CHANGE ME -> YOUR_TEST_USER\nVALID_PASSWORD = "mypassword"  # CHANGE ME -> YOUR_TEST_PASSWORD\nINVALID_USERNAME = "nobody"\nINVALID_PASSWORD = "wrong-password"\n\npytestmark = pytest.mark.login\n\n\nclass TestTheAppLogin:\n    """Happy path + negative path for the login screen."""\n\n    def test_valid_credentials_reach_secret_area(self, driver):\n        """Home -> Login Screen -> valid login -> Secret Area badge shown."""\n        secret_page = (\n            HomePage(driver)\n            .navigate_to_login()\n            .login_success(username=VALID_USERNAME, password=VALID_PASSWORD)\n        )\n        # TheApp renders an element with accessibility id "Logged in as alice"\n        assert secret_page.is_logged_in_as(VALID_USERNAME), (\n            f"Expected the Secret Area to show the logged-in user "\n            f"{VALID_USERNAME!r}"\n        )\n\n    def test_invalid_credentials_show_error_alert(self, driver):\n        """Invalid credentials must surface a native alert, not log in."""\n        login_page = HomePage(driver).navigate_to_login()\n        message = login_page.login_invalid(username=INVALID_USERNAME, password=INVALID_PASSWORD)\n\n        assert "Invalid login credentials" in message, f"Unexpected alert text: {message!r}"\n\n        # Dismiss the alert and assert we are still on the login screen\n        login_page.dismiss_alert()\n        assert login_page.is_visible(login_page.USERNAME_FIELD), (\n            "Expected to remain on the login screen after dismissing the alert"\n        )\n\n    def test_logout_returns_to_login_screen(self, driver):\n        """Logged-in users can log out again (text-based platform locators)."""\n        login_page = (\n            HomePage(driver)\n            .navigate_to_login()\n            .login_success(username=VALID_USERNAME, password=VALID_PASSWORD)\n            .logout()\n        )\n        assert login_page.is_visible(login_page.USERNAME_FIELD)\n'),
    ('utils/__init__.py', '"""Shared utilities for the mobile test framework (logging, config, waits,\ngestures, screenshots, Appium server management).\n\nModules in this package must not import from ``pages``, ``drivers`` or pytest\nso they stay reusable from scripts such as ``run_tests.py``.\n"""\n'),
    ('utils/appium_server.py', '"""Appium 2.x server lifecycle management.\n\nResponsibilities\n----------------\n* start an Appium server automatically (``AppiumServer.start()``) when none\n  is answering on the configured host:port - and only then;\n* reuse an already-running server (health check via the W3C ``/status``\n  endpoint before spawning anything);\n* stop the server at the end of the run - but **only** if this process\n  started it. Externally managed servers (CI services, Appium Desktop,\n  docker/grid) are never touched when ``settings.external`` is true;\n* redirect the server\'s stdout into ``logs/appium_server.log`` and surface\n  ERROR/WARN lines in the suite logger;\n* fail with actionable messages (log excerpts included) when anything goes\n  wrong.\n\nCompatibility: macOS/Linux + Windows (``appium.cmd`` on Windows). The\nAppium executable is located via the configured path or ``$PATH``.\n"""\n\nfrom __future__ import annotations\n\nimport os\nimport shutil\nimport socket\nimport subprocess\nimport sys\nimport threading\nimport time\nfrom pathlib import Path\nfrom typing import Optional\n\nimport requests\n\nfrom utils.config_reader import Settings\nfrom utils.errors import AppiumServerError\nfrom utils.logger import get_logger\n\nLOG = get_logger("appium_server")\n\n_POLL_INTERVAL = 0.5  # seconds between health checks while waiting\n\n\n# ---------------------------------------------------------------------------\n# module-level network helpers (reused by the driver factory too)\n# ---------------------------------------------------------------------------\ndef is_port_open(host: str, port: int, timeout: float = 0.5) -> bool:\n    """Cheap TCP probe - answers the question "is something listening?"."""\n    try:\n        with socket.create_connection((host, port), timeout=timeout):\n            return True\n    except OSError:\n        return False\n\n\ndef fetch_status(health_url: str, timeout: float = 3.0) -> Optional[dict]:\n    """GET the W3C /status endpoint; return the parsed JSON (or None).\n\n    A reachable endpoint is the definitive "an Appium server is running"\n    signal (a plain TCP listener is not enough - it could be any process).\n    """\n    try:\n        response = requests.get(health_url, timeout=timeout)\n        if response.status_code != 200:\n            return None\n        payload = response.json()\n        if isinstance(payload, dict) and "value" in payload and isinstance(payload["value"], dict):\n            return payload["value"]\n        return payload if isinstance(payload, dict) else None\n    except (requests.RequestException, ValueError):\n        return None\n\n\ndef _server_version(status: dict) -> str:\n    build = status.get("build") or {}\n    return str(build.get("version", "unknown"))\n\n\n# ---------------------------------------------------------------------------\n# server manager\n# ---------------------------------------------------------------------------\nclass AppiumServer:\n    """Manages the local Appium server process for one test run."""\n\n    def __init__(self, settings: Settings):\n        self._settings = settings\n        self._process: Optional[subprocess.Popen] = None\n        self._log_thread: Optional[threading.Thread] = None\n        self._log_file: Optional[Path] = None\n        self._started_by_us = False\n\n    # -- public API ----------------------------------------------------- #\n    @property\n    def started_by_us(self) -> bool:\n        return self._started_by_us\n\n    def is_running(self) -> bool:\n        """True when an Appium server answers on the configured endpoint."""\n        return fetch_status(self._settings.health_url(), timeout=1.5) is not None\n\n    def start(self) -> bool:\n        """Ensure an Appium server is running; returns True if this call\n        started it (and therefore owns its shutdown)."""\n        settings = self._settings\n        if settings.external:\n            return self._attach_external()\n        if self.is_running():\n            status = fetch_status(settings.health_url())\n            version = _server_version(status) if status else "unknown"\n            LOG.info(\n                "Appium server already running - reusing it (no second instance started)",\n                kv={"url": settings.server_url(), "version": version},\n            )\n            return False\n        if not settings.auto_start:\n            raise AppiumServerError(\n                f"No Appium server reachable at {settings.server_url()} and "\n                f"auto_start is disabled. Start a server yourself "\n                f"(\'appium server --address {settings.host} --port {settings.port}\') "\n                f"or enable auto_start/external in config/settings.yaml."\n            )\n        return self._launch()\n\n    def wait_until_ready(self, timeout: float | None = None) -> bool:\n        """Block until /status answers (for externally managed servers)."""\n        deadline = time.monotonic() + (timeout or self._settings.start_timeout_seconds)\n        while time.monotonic() < deadline:\n            status = fetch_status(self._settings.health_url())\n            if status is not None:\n                LOG.info("Appium server is ready", kv={"version": _server_version(status)})\n                return True\n            time.sleep(_POLL_INTERVAL)\n        return False\n\n    def stop(self) -> bool:\n        """Stop the server - but only if this run started it.\n\n        Returns True when a process was terminated by this call.\n        """\n        settings = self._settings\n        if settings.external:\n            LOG.info("Externally managed server - not stopping it")\n            return False\n        if self._process is None:\n            LOG.info("No Appium server was started by this run - nothing to stop")\n            return False\n\n        process = self._process\n        try:\n            exit_code = process.poll()\n        except Exception:\n            exit_code = None\n        if exit_code is not None:\n            LOG.warning("Appium server process already exited", kv={"exit_code": exit_code})\n            self._process = None\n            self._started_by_us = False\n            return False\n\n        LOG.info("Stopping Appium server", kv={"pid": process.pid})\n        try:\n            process.terminate()  # SIGTERM (POSIX) / TerminateProcess (Windows)\n        except OSError as exc:\n            LOG.warning("Could not send terminate signal", kv={"reason": str(exc)})\n        try:\n            process.communicate(timeout=self._settings.stop_timeout_seconds)\n        except subprocess.TimeoutExpired:\n            LOG.warning("Graceful stop timed out - killing the server process")\n            try:\n                process.kill()\n            except OSError:\n                pass\n            try:\n                process.communicate(timeout=5)\n            except subprocess.TimeoutExpired:\n                pass\n\n        self._process = None\n        self._started_by_us = False\n        LOG.info("Appium server stopped")\n        return True\n\n    def __enter__(self) -> "AppiumServer":\n        self.start()\n        return self\n\n    def __exit__(self, exc_type, exc_value, traceback) -> None:\n        self.stop()\n\n    # -- internals ------------------------------------------------------ #\n    def _attach_external(self) -> bool:\n        """Validate connectivity to an externally managed server."""\n        settings = self._settings\n        LOG.info(\n            "External Appium server mode",\n            kv={"url": settings.server_url(), "timeout_s": settings.start_timeout_seconds},\n        )\n        if self.wait_until_ready():\n            LOG.info("Connected to externally managed Appium server")\n            return False\n        raise AppiumServerError(\n            f"External Appium server not reachable at {settings.server_url()} "\n            f"after {settings.start_timeout_seconds}s. Start it first, e.g.:\\n"\n            f"  appium server --address {settings.host} --port {settings.port}\\n"\n            f"or point the framework at the right host/port in config/settings.yaml."\n        )\n\n    def _resolve_binary(self) -> str:\n        configured = self._settings.binary.strip()\n        if configured:\n            if Path(configured).exists():\n                return configured\n            found = shutil.which(configured)\n            if found:\n                return found\n            raise AppiumServerError(\n                f"Configured APPIUM_BINARY {configured!r} does not exist. "\n                f"Fix settings.yaml / the APPIUM_BINARY environment variable."\n            )\n        found = shutil.which("appium")\n        if not found and sys.platform == "win32":\n            found = shutil.which("appium.cmd")  # npm .cmd shim on Windows\n        if not found:\n            raise AppiumServerError(\n                "The \'appium\' executable was not found on $PATH. Install it with:\\n"\n                "  npm install -g appium@2\\n"\n                "  appium driver install uiautomator2    # Android\\n"\n                "  appium driver install xcuitest        # iOS\\n"\n                "or set APPIUM_BINARY to the absolute path of the executable."\n            )\n        return found\n\n    def _launch(self) -> bool:\n        settings = self._settings\n        binary = self._resolve_binary()\n\n        command = [\n            binary,\n            "server",\n            "--address", settings.host,\n            "--port", str(settings.port),\n            "--log-level", settings.server_log_level,\n            "--log-no-colors",\n            "--log-timestamp",\n        ]\n        if settings.base_path.strip():\n            command += ["--base-path", settings.base_path.strip("/") or "/"]\n        if settings.use_drivers:\n            command += ["--use-drivers", ",".join(settings.use_drivers)]\n\n        log_dir = settings.log_dir\n        log_dir.mkdir(parents=True, exist_ok=True)\n        self._log_file = log_dir / "appium_server.log"\n\n        LOG.info(\n            "Starting Appium server",\n            kv={"command": " ".join(command), "log_file": str(self._log_file)},\n        )\n\n        # Detach the child from our process group so cleanup works cleanly\n        # on both POSIX and Windows.\n        kwargs: dict = {}\n        if os.name == "nt":\n            kwargs["creationflags"] = subprocess.CREATE_NEW_PROCESS_GROUP\n        else:\n            kwargs["start_new_session"] = True\n\n        try:\n            self._process = subprocess.Popen(\n                command,\n                stdout=subprocess.PIPE,\n                stderr=subprocess.STDOUT,\n                text=True,\n                encoding="utf-8",\n                errors="replace",\n                bufsize=1,\n                **kwargs,\n            )\n        except OSError as exc:\n            raise AppiumServerError(f"Failed to launch Appium server: {exc}") from exc\n\n        self._log_thread = threading.Thread(\n            target=self._consume_stdout,\n            name="appium-server-log",\n            daemon=True,\n        )\n        self._log_thread.start()\n\n        # Wait for health, watching for early process death\n        deadline = time.monotonic() + settings.start_timeout_seconds\n        while time.monotonic() < deadline:\n            exit_code = self._process.poll()\n            if exit_code is not None:\n                self._report_dead_process(exit_code)\n                self._process = None\n                raise AppiumServerError(\n                    f"Appium server exited during startup (exit code {exit_code}). "\n                    f"See {self._log_file} for details."\n                )\n            status = fetch_status(settings.health_url(), timeout=1.0)\n            if status is not None:\n                self._started_by_us = True\n                LOG.info(\n                    "Appium server started successfully",\n                    kv={\n                        "pid": self._process.pid,\n                        "url": settings.server_url(),\n                        "version": _server_version(status),\n                        "log_file": str(self._log_file),\n                    },\n                )\n                return True\n            time.sleep(_POLL_INTERVAL)\n\n        # Startup timeout: clean up and raise with the log tail\n        try:\n            self._process.terminate()\n        except OSError:\n            pass\n        self._process = None\n        raise AppiumServerError(\n            f"Appium server did not become healthy at {settings.server_url()} "\n            f"within {settings.start_timeout_seconds}s.\\n"\n            f"Last lines of {self._log_file}:\\n{self.log_tail(25)}"\n        )\n\n    def _report_dead_process(self, exit_code: int) -> None:\n        LOG.error(\n            "Appium server process died",\n            kv={"exit_code": exit_code, "log_file": str(self._log_file)},\n        )\n        LOG.error(f"Server log tail:\\n{self.log_tail(25)}")\n\n    def log_tail(self, lines: int = 25) -> str:\n        """Return the last ``lines`` of the captured server log (\'\' if none)."""\n        if self._log_file is None or not self._log_file.exists():\n            return "(no log captured yet)"\n        try:\n            content = self._log_file.read_text(encoding="utf-8", errors="replace")\n        except OSError:\n            return "(log not readable)"\n        tail = content.strip().splitlines()[-lines:]\n        return "\\n".join(tail)\n\n    def _consume_stdout(self) -> None:\n        """Copy server stdout into appium_server.log, mirroring ERR/WARN."""\n        if self._process is None or self._process.stdout is None:\n            return\n        handle = self._log_file.open("a", encoding="utf-8", errors="replace", buffering=1)\n        try:\n            for raw_line in self._process.stdout:\n                line = raw_line.rstrip()\n                if not line:\n                    continue\n                handle.write(line + "\\n")\n                handle.flush()\n                upper = line.upper()\n                if "ERROR" in upper:\n                    LOG.error(f"[appium-server] {line}")\n                elif "WARN" in upper or "DEPRECAT" in upper:\n                    LOG.warning(f"[appium-server] {line}")\n                else:\n                    LOG.debug(f"[appium-server] {line}")\n        except Exception:  # pragma: no cover - best effort tailing\n            pass\n        finally:\n            handle.flush()\n            handle.close()\n'),
    ('utils/config_reader.py', '"""Configuration loading and resolution.\n\nReads, in this order of precedence (highest wins):\n\n1. explicit arguments (e.g. ``--platform ios`` on the CLI)\n2. environment variables (from the shell / CI or a local ``.env`` file)\n3. ``config/settings.yaml`` for global settings\n4. ``config/<platform>.yaml`` for the target device/app configuration\n\nOnly the *resolved* platform has its platform YAML loaded, which keeps\nAndroid and iOS configuration strictly separated.\n"""\n\nfrom __future__ import annotations\n\nimport os\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\n\nimport yaml\nfrom dotenv import load_dotenv\n\nfrom utils.errors import ConfigError\n\nPROJECT_ROOT = Path(__file__).resolve().parent.parent\nCONFIG_DIR = PROJECT_ROOT / "config"\nSUPPORTED_PLATFORMS = ("android", "ios")\nPLATFORM_FILES = {"android": "android.yaml", "ios": "ios.yaml"}\n\n# Load optional .env (never fails, never overrides real environment)\nload_dotenv(PROJECT_ROOT / ".env", override=False)\n\n\n# ---------------------------------------------------------------------------\n# helpers\n# ---------------------------------------------------------------------------\ndef _env_str(key: str, default: str = "") -> str:\n    value = os.getenv(key, "").strip()\n    return value if value else default\n\n\ndef _env_bool(key: str, default: bool) -> bool:\n    value = os.getenv(key)\n    if value is None:\n        return default\n    return value.strip().lower() in ("1", "true", "yes", "on")\n\n\ndef resolve_platform(cli_platform: str | None = None) -> str:\n    """Return a validated platform name: CLI flag > APP_PLATFORM > android."""\n    platform = (cli_platform or _env_str("APP_PLATFORM", "android")).strip().lower()\n    if platform not in SUPPORTED_PLATFORMS:\n        raise ConfigError(\n            f"Unsupported platform {platform!r}. Choose one of: "\n            f"{\', \'.join(SUPPORTED_PLATFORMS)} (--platform flag or APP_PLATFORM env)."\n        )\n    return platform\n\n\ndef _read_yaml(path: Path) -> dict:\n    if not path.exists():\n        raise ConfigError(\n            f"Configuration file not found: {path}\\n"\n            f"Create it from the YAML templates or re-run the framework "\n            f"creation script."\n        )\n    with path.open("r", encoding="utf-8") as stream:\n        data = yaml.safe_load(stream)\n    if not isinstance(data, dict):\n        raise ConfigError(f"Configuration file {path} must contain a YAML mapping.")\n    return data\n\n\ndef _require(container: dict, key: str, source: str) -> object:\n    if key not in container or container[key] is None:\n        raise ConfigError(f"Missing required key {key!r} in {source}.")\n    return container[key]\n\n\n# ---------------------------------------------------------------------------\n# settings object\n# ---------------------------------------------------------------------------\n@dataclass\nclass Settings:\n    """Fully resolved runtime settings for one test run."""\n\n    platform: str\n    device: dict = field(default_factory=dict)\n    project_root: Path = PROJECT_ROOT\n\n    # appium server\n    host: str = "127.0.0.1"\n    port: int = 4723\n    base_path: str = ""\n    binary: str = ""\n    auto_start: bool = True\n    external: bool = False\n    start_timeout_seconds: int = 30\n    stop_timeout_seconds: int = 10\n    server_log_level: str = "info"\n    use_drivers: list = field(default_factory=list)\n\n    # paths (absolute)\n    log_dir: Path = PROJECT_ROOT / "logs"\n    screenshot_dir: Path = PROJECT_ROOT / "artifacts" / "screenshots"\n    page_source_dir: Path = PROJECT_ROOT / "artifacts" / "page_source"\n\n    # timeouts (seconds)\n    timeout_default: int = 15\n    timeout_short: int = 5\n    timeout_long: int = 30\n\n    # logging\n    log_level: str = "INFO"\n\n    # ------------------------------------------------------------------ #\n    def server_url(self) -> str:\n        """Base URL the Appium client connects to (no trailing slash)."""\n        base = self.base_path.strip("/")\n        return f"http://{self.host}:{self.port}" + (f"/{base}" if base else "")\n\n    def health_url(self) -> str:\n        """URL of the W3C ``/status`` endpoint used for health checks."""\n        return f"{self.server_url()}/status"\n\n    def resolve_app_path(self) -> str:\n        """Absolute path to the app under test (\'\' when the app is installed\n        on the device and app_path was left empty)."""\n        raw = str(self.device.get("app_path", "") or "").strip()\n        if not raw:\n            return ""\n        path = Path(raw)\n        if not path.is_absolute():\n            path = self.project_root / path\n        return str(path)\n\n    def summary(self) -> str:\n        """One-line human readable summary used in logs and run banners."""\n        udid = self.device.get("udid") or "-"\n        return (\n            f"platform={self.platform} device_name={self.device.get(\'device_name\')!r} "\n            f"udid={udid} app={self.device.get(\'app_path\')!r} "\n            f"appium={self.host}:{self.port}"\n        )\n\n\ndef _load_device_config(platform: str) -> dict:\n    path = CONFIG_DIR / PLATFORM_FILES[platform]\n    data = _read_yaml(path)\n    required = ("platform_name", "automation_name", "device_name")\n    for key in required:\n        _require(data, key, str(path))\n    return data\n\n\ndef _merge_appium_settings(data: dict) -> dict:\n    """Appium server settings from settings.yaml, overridden by APPIUM_* env vars.\n\n    ``external``/``auto_start`` semantics:\n    * external=True  -> the framework never starts/stops the server (CI,\n      Appium Desktop, docker, grid...). APP_EXTERNAL=true forces this.\n    * external=False and auto_start=True  -> start automatically if needed,\n      stop at session end only if this run started it (default).\n    * external=False and auto_start=False -> fail with clear guidance when\n      no server is reachable.\n    """\n    appium = data.get("appium") or {}\n    external_default = bool(appium.get("external", False))\n    external = _env_bool("APP_EXTERNAL", external_default)\n    return {\n        "host": _env_str("APPIUM_HOST", str(appium.get("host", "127.0.0.1"))),\n        "port": int(_env_str("APPIUM_PORT", str(appium.get("port", 4723)))),\n        "base_path": str(appium.get("base_path", "") or "").strip(),\n        "binary": _env_str("APPIUM_BINARY", str(appium.get("binary", "") or "")),\n        "auto_start": bool(appium.get("auto_start", True)) if not external else False,\n        "external": external,\n        "start_timeout_seconds": int(appium.get("start_timeout_seconds", 30)),\n        "stop_timeout_seconds": int(appium.get("stop_timeout_seconds", 10)),\n        "server_log_level": str(appium.get("log_level", "info")).lower(),\n        "use_drivers": list(appium.get("use_drivers") or []),\n    }\n\n\ndef load_settings(platform: str | None = None) -> Settings:\n    """Build a resolved :class:`Settings` for the given platform."""\n    platform = resolve_platform(platform)\n    settings_file = _read_yaml(CONFIG_DIR / "settings.yaml")\n    device = _load_device_config(platform)\n    appium = _merge_appium_settings(settings_file)\n\n    # Environment overrides that target the device under test\n    if _env_str("APP_DEVICE_NAME"):\n        device["device_name"] = _env_str("APP_DEVICE_NAME")\n    if _env_str("APP_UDID"):\n        device["udid"] = _env_str("APP_UDID")\n    if _env_str("APP_PATH"):\n        device["app_path"] = _env_str("APP_PATH")\n        device["_app_path_origin"] = "env"  # informational\n\n    paths = settings_file.get("paths") or {}\n    timeouts = settings_file.get("timeouts") or {}\n    logging_cfg = settings_file.get("logging") or {}\n\n    def _root_relative(raw: str) -> Path:\n        path = Path(raw)\n        return path if path.is_absolute() else PROJECT_ROOT / path\n\n    settings = Settings(\n        platform=platform,\n        device=device,\n        host=appium["host"],\n        port=appium["port"],\n        base_path=appium["base_path"],\n        binary=appium["binary"],\n        auto_start=appium["auto_start"],\n        external=appium["external"],\n        start_timeout_seconds=appium["start_timeout_seconds"],\n        stop_timeout_seconds=appium["stop_timeout_seconds"],\n        server_log_level=appium["server_log_level"],\n        use_drivers=appium["use_drivers"],\n        log_dir=_root_relative(str(paths.get("logs", "logs"))),\n        screenshot_dir=_root_relative(str(paths.get("screenshots", "artifacts/screenshots"))),\n        page_source_dir=_root_relative(str(paths.get("page_source", "artifacts/page_source"))),\n        timeout_default=int(timeouts.get("default", 15)),\n        timeout_short=int(timeouts.get("short", 5)),\n        timeout_long=int(timeouts.get("long", 30)),\n        log_level=str(logging_cfg.get("level", "INFO")).upper(),\n    )\n    return settings\n'),
    ('utils/errors.py', '"""Framework-wide exception types.\n\nKeeping them in one place avoids circular imports and gives tests a single\nset of exceptions they can catch/treat in a custom way.\n"""\n\n\nclass FrameworkError(RuntimeError):\n    """Base class for all framework errors."""\n\n\nclass ConfigError(FrameworkError):\n    """Raised when configuration files/env/CLI are missing or invalid."""\n\n\nclass AppiumServerError(FrameworkError):\n    """Raised when the Appium server cannot be started/stopped/reached."""\n\n\nclass DriverInitializationError(FrameworkError):\n    """Raised when a WebDriver session cannot be created.\n\n    The message is intentionally verbose: it points the user at the most\n    common causes (device not connected, app path wrong, drivers missing).\n    """\n\n\nclass GestureNotSupportedError(FrameworkError, NotImplementedError):\n    """Raised when a gesture is not available on the current platform."""\n\n\nclass ElementNotFoundError(FrameworkError):\n    """Raised by scroll-to-element helpers when the target never appears."""\n\n\nclass WaitTimeoutError(FrameworkError, TimeoutError):\n    """Raised by custom wait helpers when the condition did not become true."""\n'),
    ('utils/gestures.py', '"""Reusable mobile gesture helpers (Android + iOS).\n\nAPI philosophy\n--------------\n* **W3C WebDriver Actions** (Selenium ``PointerInput`` + ``/actions``\n  endpoint) are the default engine: one implementation, identical behaviour\n  on both drivers, deterministic timing.\n* **Native ``mobile:`` shortcut commands** (``mobile: doubleClickGesture``,\n  ``mobile: touchAndHold``, ``mobile: pinchOpenGesture``...) are used where\n  they are the *recommended, maintained* API and give platform-optimised\n  physics (e.g. Android speed-based gestures, iOS ``pinchWithScale``).\n\n  .. deprecated:: TouchAction / MultiAction (JSONWP) were removed from both\n     Appium 2 and the Python client (v4+) - this module never uses them.\n\nDirection semantics\n-------------------\nEvery ``swipe_*`` / ``scroll*`` method is expressed as **finger travel**:\n``swipe_up`` = finger moves from a low Y to a high Y. The content therefore\nmoves *up* and content *further down the page* is revealed (what most people\nmean by "scroll down the page"). ``swipe_down`` goes back up the page.\nHorizontal gestures follow the same logic.\n\nCoordinates are physical pixels in the viewport, exactly like\n``get_window_size()`` reports them. This matches Appium on both platforms;\niOS *points* equal pixels on modern devices (1x-3x scale handled by WDA).\n\nPlatform differences worth knowing\n----------------------------------\n* ``back`` is Android-only (iOS has no system back; apps expose their own\n  navigation buttons - tap those via page objects).\n* iOS cannot long-press coordinates *or* elements below the minimum\n  ``pressForDuration`` threshold; durations < 0.5s degrade into a tap.\n* ``fling`` (native, velocity-driven) exists on Android only; on iOS use\n  ``flick`` (fast W3C swipe) instead.\n* ``double_tap`` and ``long_press`` fall back to plain W3C sequences when\n  the native shortcut fails (e.g. driver versions without the command).\n* ``pinch`` on iOS maps to XCUITest ``pinchWithScale``; on Android to the\n  UiAutomator2 pinch gestures. Fallbacks are attempted for both.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Any, Tuple\n\nfrom selenium.common.exceptions import (\n    NoSuchElementException,\n    StaleElementReferenceException,\n    WebDriverException,\n)\nfrom selenium.webdriver.common.actions import interaction\nfrom selenium.webdriver.common.actions.pointer_input import PointerInput\nfrom selenium.webdriver.remote.command import Command\nfrom selenium.webdriver.remote.webelement import WebElement\n\nfrom utils.errors import ElementNotFoundError, GestureNotSupportedError\nfrom utils.logger import get_logger\n\nLOG = get_logger("utils.gestures")\n\n# Seconds between the pointer-up of one tap and the pointer-down of the next\n# in a double tap (part of the W3C fallback sequence).\n_DOUBLE_TAP_PAUSE = 0.06\n\n# Minimum long-press duration Android registers as a long click.\n_ANDROID_LONG_PRESS_MS = 500\n\n\n# ---------------------------------------------------------------------------\n# internal helpers\n# ---------------------------------------------------------------------------\ndef _new_touch(name: str = "touch") -> PointerInput:\n    return PointerInput(interaction.POINTER_TOUCH, name)\n\n\ndef _dispatch(driver: Any, pointers: list[PointerInput], gesture: str, **kv: Any) -> None:\n    """Send the encoded W3C action payloads of one or more pointers."""\n    payloads = [pointer.encode() for pointer in pointers]\n    payloads = [payload for payload in payloads if payload.get("actions")]\n    if not payloads:\n        LOG.warning("Gesture produced no actions; nothing dispatched", kv={"gesture": gesture})\n        return\n    LOG.debug("Dispatching W3C actions", kv={"gesture": gesture, "pointers": len(payloads), **kv})\n    driver.execute(Command.W3C_ACTIONS, {"actions": payloads})\n    LOG.info("Gesture performed", kv={"gesture": gesture, **kv})\n\n\ndef _mobile(driver: Any, script: str, params: dict, gesture: str, **kv: Any) -> Any:\n    """Execute a native ``mobile:`` shortcut with logging."""\n    LOG.debug("Executing mobile command", kv={"script": script, "params": params})\n    result = driver.execute_script(script, params)\n    LOG.info("Gesture performed (native)", kv={"gesture": gesture, "script": script, **kv})\n    return result\n\n\ndef detect_platform(driver: Any) -> str:\n    """Return \'ios\' or \'android\' from the active session capabilities."""\n    capabilities = getattr(driver, "capabilities", None) or {}\n    platform = str(capabilities.get("platformName", "")).lower()\n    return "ios" if platform == "ios" else "android"\n\n\ndef _element_center(element: Any) -> Tuple[int, int]:\n    """Centre point (viewport pixels) of an element via its rect.\n\n    Falls back to location + size for old drivers that lack ``rect``.\n    """\n    try:\n        rect = element.rect\n        x = rect.get("x", 0)\n        y = rect.get("y", 0)\n        width = rect.get("width", 0)\n        height = rect.get("height", 0)\n        if width and height:\n            return int(x + width / 2), int(y + height / 2)\n    except Exception:\n        pass\n    location = element.location  # {"x": ..., "y": ...}\n    size = element.size  # {"width": ..., "height": ...}\n    return int(location["x"] + size["width"] / 2), int(location["y"] + size["height"] / 2)\n\n\ndef _viewport(driver: Any) -> Tuple[int, int]:\n    size = driver.get_window_size()\n    return int(size["width"]), int(size["height"])\n\n\ndef _element_rect(element: Any) -> dict:\n    try:\n        return element.rect\n    except (StaleElementReferenceException, WebDriverException):\n        raise\n    except Exception:\n        location = element.location\n        size = element.size\n        return {"x": location["x"], "y": location["y"], "width": size["width"], "height": size["height"]}\n\n\ndef _point_in_viewport(driver: Any, element: Any, container: Any = None) -> bool:\n    """True when the element\'s frame intersects the container (or viewport)."""\n    try:\n        rect = _element_rect(element)\n    except (StaleElementReferenceException, NoSuchElementException):\n        return False\n    if not rect.get("width") or not rect.get("height"):\n        return False\n    if container is not None:\n        try:\n            c = _element_rect(container)\n            cw, ch, cx, cy = c["width"], c["height"], c["x"], c["y"]\n        except Exception:\n            cw, ch, cx, cy = *_viewport(driver), 0, 0\n    else:\n        cw, ch = _viewport(driver)\n        cx = cy = 0\n    overlap_x = min(rect["x"] + rect["width"], cx + cw) - max(rect["x"], cx)\n    overlap_y = min(rect["y"] + rect["height"], cy + ch) - max(rect["y"], cy)\n    return overlap_x > 0 and overlap_y > 0\n\n\n# ---------------------------------------------------------------------------\n# tap family\n# ---------------------------------------------------------------------------\ndef tap_at(driver: Any, x: float, y: float) -> None:\n    """Tap the screen at absolute viewport coordinates (pixels)."""\n    pointer = _new_touch("tap")\n    pointer.create_pointer_move(duration=0, x=int(x), y=int(y))\n    pointer.create_pointer_down(button=0)\n    pointer.create_pointer_up(button=0)\n    _dispatch(driver, [pointer], "tap", at=(int(x), int(y)))\n\n\ndef tap_element(driver: Any, element: Any) -> None:\n    """Tap the centre of an element (W3C, works on both platforms)."""\n    x, y = _element_center(element)\n    tap_at(driver, x, y)\n\n\ndef _w3c_double_tap(driver: Any, x: int, y: int) -> None:\n    pointer = _new_touch("double_tap")\n    for _ in range(2):\n        pointer.create_pointer_move(duration=0, x=x, y=y)\n        pointer.create_pointer_down(button=0)\n        pointer.create_pointer_up(button=0)\n        pointer.create_pause(_DOUBLE_TAP_PAUSE)\n    _dispatch(driver, [pointer], "double_tap", at=(x, y))\n\n\ndef double_tap_at(driver: Any, x: float, y: float) -> None:\n    """Double tap at screen coordinates.\n\n    Android: ``mobile: doubleClickGesture`` accepts coordinates.\n    iOS: the XCUITest ``mobile: doubleTap`` shortcut only targets elements,\n    so coordinate double taps run as two W3C taps 60 ms apart.\n    """\n    platform = detect_platform(driver)\n    if platform == "android":\n        try:\n            _mobile(\n                driver,\n                "mobile: doubleClickGesture",\n                {"x": int(x), "y": int(y)},\n                "double_tap",\n                at=(x, y),\n            )\n            return\n        except WebDriverException as exc:\n            LOG.warning(\n                "Native double tap failed; falling back to W3C double tap",\n                kv={"platform": platform, "reason": str(exc)[:200]},\n            )\n    else:\n        LOG.debug("iOS doubleTap shortcut is element-only; using W3C double tap")\n    _w3c_double_tap(driver, int(x), int(y))\n\n\ndef double_tap_element(driver: Any, element: Any) -> None:\n    """Double tap the centre of an element (native shortcut, W3C fallback).\n\n    Android: ``mobile: doubleClickGesture``; iOS: ``mobile: doubleTap``.\n    """\n    platform = detect_platform(driver)\n    params = {"elementId": element.id}\n    try:\n        if platform == "android":\n            _mobile(driver, "mobile: doubleClickGesture", params, "double_tap_element")\n        else:\n            _mobile(driver, "mobile: doubleTap", params, "double_tap_element")\n    except WebDriverException as exc:\n        LOG.warning(\n            "Native double tap on element failed; falling back to W3C",\n            kv={"platform": platform, "reason": str(exc)[:200]},\n        )\n        x, y = _element_center(element)\n        _w3c_double_tap(driver, x, y)\n\n\n# ---------------------------------------------------------------------------\n# long press\n# ---------------------------------------------------------------------------\ndef _w3c_long_press(driver: Any, x: int, y: int, duration_seconds: float) -> None:\n    pointer = _new_touch("long_press")\n    pointer.create_pointer_move(duration=0, x=x, y=y)\n    pointer.create_pointer_down(button=0)\n    pointer.create_pause(duration_seconds)\n    pointer.create_pointer_up(button=0)\n    _dispatch(driver, [pointer], "long_press", at=(x, y), duration_s=duration_seconds)\n\n\ndef _native_long_press(driver: Any, x: int | None, y: int | None, element: Any | None, duration_seconds: float) -> None:\n    platform = detect_platform(driver)\n    if platform == "android":\n        params = {"duration": int(duration_seconds * 1000)}\n        if element is not None:\n            params["elementId"] = element.id\n        else:\n            params.update({"x": int(x), "y": int(y)})\n        _mobile(driver, "mobile: longClickGesture", params, "long_press", duration_ms=duration_seconds * 1000)\n    else:\n        # XCUITest touchAndHold: duration in SECONDS and it is mandatory\n        params = {"duration": duration_seconds}\n        if element is not None:\n            params["elementId"] = element.id\n        else:\n            params.update({"x": int(x), "y": int(y)})\n        _mobile(driver, "mobile: touchAndHold", params, "long_press", duration_s=duration_seconds)\n\n\ndef long_press(\n    driver: Any,\n    element: Any | None = None,\n    x: float | None = None,\n    y: float | None = None,\n    duration_seconds: float = 1.0,\n) -> None:\n    """Long-press an element or screen coordinates.\n\n    Android: ``mobile: longClickGesture`` (duration in ms, >= 500 ms is\n    registered as a long click). iOS: ``mobile: touchAndHold`` (duration in\n    seconds). Falls back to a W3C down-hold-up sequence on failure.\n    """\n    if element is None and (x is None or y is None):\n        raise ValueError("long_press() needs either an element or both x and y.")\n    try:\n        _native_long_press(driver, x, y, element, duration_seconds)\n    except WebDriverException as exc:\n        LOG.warning(\n            "Native long press failed; falling back to W3C sequence",\n            kv={"reason": str(exc)[:200]},\n        )\n        if element is not None:\n            x, y = _element_center(element)\n        _w3c_long_press(driver, int(x), int(y), duration_seconds)\n\n\ndef long_press_element(driver: Any, element: Any, duration_seconds: float = 1.0) -> None:\n    """Convenience wrapper: long-press the centre of ``element``."""\n    long_press(driver, element=element, duration_seconds=duration_seconds)\n\n\n# ---------------------------------------------------------------------------\n# swipe / scroll (W3C, deterministic on both platforms)\n# ---------------------------------------------------------------------------\ndef swipe_between_coordinates(\n    driver: Any,\n    start_x: float,\n    start_y: float,\n    end_x: float,\n    end_y: float,\n    duration_ms: int = 700,\n) -> None:\n    """Swipe the finger from (start_x, start_y) to (end_x, end_y).\n\n    ``duration_ms`` controls the speed: ~700-1000 ms feels like a deliberate\n    drag-scroll, 100-250 ms like a flick. Coordinates are viewport pixels.\n    """\n    pointer = _new_touch("swipe")\n    pointer.create_pointer_move(duration=0, x=int(start_x), y=int(start_y))\n    pointer.create_pointer_down(button=0)\n    pointer.create_pointer_move(duration=duration_ms, x=int(end_x), y=int(end_y))\n    pointer.create_pause(0.05)  # let the driver register the move end\n    pointer.create_pointer_up(button=0)\n    _dispatch(\n        driver,\n        [pointer],\n        "swipe_between_coordinates",\n        start=(int(start_x), int(start_y)),\n        end=(int(end_x), int(end_y)),\n        duration_ms=duration_ms,\n    )\n\n\ndef swipe_between_elements(\n    driver: Any,\n    source_element: Any,\n    target_element: Any,\n    duration_ms: int = 700,\n) -> None:\n    """Swipe from the centre of one element to the centre of another."""\n    sx, sy = _element_center(source_element)\n    tx, ty = _element_center(target_element)\n    swipe_between_coordinates(driver, sx, sy, tx, ty, duration_ms=duration_ms)\n\n\ndef _region_points(driver: Any, element: Any | None, direction: str, distance_fraction: float) -> tuple:\n    """Return (start, end) viewport points for a swipe across an element (or\n    the whole screen). Direction = finger travel; coordinates are clamped to\n    the region so large fractions never send the finger off-screen."""\n    if element is not None:\n        rect = _element_rect(element)\n        left, top = int(rect["x"]), int(rect["y"])\n        width, height = int(rect["width"]), int(rect["height"])\n    else:\n        left, top = 0, 0\n        width, height = _viewport(driver)\n\n    if width <= 0 or height <= 0:\n        width, height = _viewport(driver)\n        left = top = 0\n\n    def _clamp(value: int, low: int, high: int) -> int:\n        return max(low, min(value, high))\n\n    x_lo, x_hi = left, left + max(width - 1, 0)\n    y_lo, y_hi = top, top + max(height - 1, 0)\n    cx = _clamp(left + width // 2, x_lo, x_hi)\n    cy = _clamp(top + height // 2, y_lo, y_hi)\n    d = max(0.0, min(distance_fraction, 1.0))  # fraction of the region travelled\n\n    if direction == "up":\n        return (cx, _clamp(top + int(height * 0.85), y_lo, y_hi)), (\n            cx,\n            _clamp(top + int(height * (0.85 - d)), y_lo, y_hi),\n        )\n    if direction == "down":\n        return (cx, _clamp(top + int(height * 0.15), y_lo, y_hi)), (\n            cx,\n            _clamp(top + int(height * (0.15 + d)), y_lo, y_hi),\n        )\n    if direction == "left":\n        return (_clamp(left + int(width * 0.85), x_lo, x_hi), cy), (\n            _clamp(left + int(width * (0.85 - d)), x_lo, x_hi),\n            cy,\n        )\n    if direction == "right":\n        return (_clamp(left + int(width * 0.15), x_lo, x_hi), cy), (\n            _clamp(left + int(width * (0.15 + d)), x_lo, x_hi),\n            cy,\n        )\n    raise ValueError(f"direction must be up/down/left/right, got {direction!r}")\n\n\ndef _swipe_direction(\n    driver: Any,\n    direction: str,\n    element: Any | None = None,\n    distance_fraction: float = 0.75,\n    duration_ms: int = 700,\n    gesture_name: str = "swipe",\n) -> None:\n    (sx, sy), (ex, ey) = _region_points(driver, element, direction, distance_fraction)\n    swipe_between_coordinates(driver, sx, sy, ex, ey, duration_ms=duration_ms)\n    LOG.info("Directional swipe", kv={"gesture": gesture_name, "direction": direction, "element": element is not None})\n\n\ndef swipe_up(driver: Any, element: Any | None = None, distance_fraction: float = 0.75, duration_ms: int = 700) -> None:\n    """Finger travels upward; content further down the page is revealed."""\n    _swipe_direction(driver, "up", element, distance_fraction, duration_ms, "swipe_up")\n\n\ndef swipe_down(driver: Any, element: Any | None = None, distance_fraction: float = 0.75, duration_ms: int = 700) -> None:\n    """Finger travels downward; content further up the page is revealed."""\n    _swipe_direction(driver, "down", element, distance_fraction, duration_ms, "swipe_down")\n\n\ndef swipe_left(driver: Any, element: Any | None = None, distance_fraction: float = 0.75, duration_ms: int = 700) -> None:\n    """Finger travels left; content to the right is revealed."""\n    _swipe_direction(driver, "left", element, distance_fraction, duration_ms, "swipe_left")\n\n\ndef swipe_right(driver: Any, element: Any | None = None, distance_fraction: float = 0.75, duration_ms: int = 700) -> None:\n    """Finger travels right; content to the left is revealed."""\n    _swipe_direction(driver, "right", element, distance_fraction, duration_ms, "swipe_right")\n\n\n# scroll_* are semantic aliases of the swipe_* family\ndef scroll_up(driver: Any, element: Any | None = None, distance_fraction: float = 0.75, duration_ms: int = 700) -> None:\n    """Scroll the page downwards (finger travels up)."""\n    swipe_up(driver, element, distance_fraction, duration_ms)\n\n\ndef scroll_down(driver: Any, element: Any | None = None, distance_fraction: float = 0.75, duration_ms: int = 700) -> None:\n    """Scroll the page upwards (finger travels down)."""\n    swipe_down(driver, element, distance_fraction, duration_ms)\n\n\ndef scroll_left(driver: Any, element: Any | None = None, distance_fraction: float = 0.75, duration_ms: int = 700) -> None:\n    swipe_left(driver, element, distance_fraction, duration_ms)\n\n\ndef scroll_right(driver: Any, element: Any | None = None, distance_fraction: float = 0.75, duration_ms: int = 700) -> None:\n    swipe_right(driver, element, distance_fraction, duration_ms)\n\n\n# ---------------------------------------------------------------------------\n# flick / fling\n# ---------------------------------------------------------------------------\ndef flick_between_coordinates(\n    driver: Any,\n    start_x: float,\n    start_y: float,\n    end_x: float,\n    end_y: float,\n    duration_ms: int = 120,\n) -> None:\n    """Fast short swipe = flick (W3C; both platforms).\n\n    iOS note: there is no XCUITest native flick command; a quick W3C swipe\n    is the recommended equivalent.\n    """\n    swipe_between_coordinates(driver, start_x, start_y, end_x, end_y, duration_ms=duration_ms)\n\n\ndef flick_up(driver: Any, element: Any | None = None, distance_fraction: float = 0.5, duration_ms: int = 120) -> None:\n    """Quick flick upward (reveals content below the fold)."""\n    _swipe_direction(driver, "up", element, distance_fraction, duration_ms, "flick_up")\n\n\ndef flick_down(driver: Any, element: Any | None = None, distance_fraction: float = 0.5, duration_ms: int = 120) -> None:\n    _swipe_direction(driver, "down", element, distance_fraction, duration_ms, "flick_down")\n\n\ndef flick_left(driver: Any, element: Any | None = None, distance_fraction: float = 0.5, duration_ms: int = 120) -> None:\n    _swipe_direction(driver, "left", element, distance_fraction, duration_ms, "flick_left")\n\n\ndef flick_right(driver: Any, element: Any | None = None, distance_fraction: float = 0.5, duration_ms: int = 120) -> None:\n    _swipe_direction(driver, "right", element, distance_fraction, duration_ms, "flick_right")\n\n\ndef fling_android(driver: Any, direction: str, speed: int | None = None) -> None:\n    """Native Android velocity fling (``mobile: flingGesture``).\n\n    Only available on Android. Use ``flick_*`` on iOS instead.\n    """\n    platform = detect_platform(driver)\n    if platform != "android":\n        raise GestureNotSupportedError(\n            "fling_android() requires the UiAutomator2 driver (Android). "\n            "On iOS use flick_up()/flick_down()/... instead."\n        )\n    params: dict = {"direction": direction}\n    if speed is not None:\n        params["speed"] = int(speed)\n    _mobile(driver, "mobile: flingGesture", params, "fling_android", direction=direction)\n\n\n# ---------------------------------------------------------------------------\n# scroll to element\n# ---------------------------------------------------------------------------\ndef _locator_of(by: Any, value: Any) -> tuple:\n    if value is None and isinstance(by, (tuple, list)) and len(by) == 2:\n        return tuple(by)\n    return (by, value)\n\n\ndef scroll_to_element(\n    driver: Any,\n    by: Any,\n    value: Any = None,\n    direction: str = "up",\n    max_swipes: int = 10,\n    container: Any | None = None,\n    distance_fraction: float = 0.7,\n) -> WebElement:\n    """Swipe repeatedly until the target element scrolls into the viewport.\n\n    Args:\n        by/value: locator (or a ready-made ``(by, value)`` tuple as ``by``).\n        direction: finger travel direction used to look for the element.\n                   \'up\' reveals content below (the common case).\n        max_swipes: safety valve before :class:`ElementNotFoundError`.\n        container: optional scrollable container element to scroll inside and\n                   to use as the visibility reference.\n        distance_fraction: how far each swipe travels.\n\n    Returns the visible element. Raises :class:`ElementNotFoundError` when\n    the element did not appear after ``max_swipes`` attempts.\n    """\n    locator = _locator_of(by, value)\n    LOG.info("Scrolling to element", kv={"locator": (locator[0], locator[1]), "direction": direction, "max_swipes": max_swipes})\n    last_error: Exception | None = None\n\n    for attempt in range(1, max_swipes + 1):\n        try:\n            element = driver.find_element(*locator)\n            if _point_in_viewport(driver, element, container):\n                LOG.info("Element found in viewport", kv={"attempt": attempt, "locator": (locator[0], locator[1])})\n                return element\n            LOG.debug("Element exists but is outside the viewport", kv={"attempt": attempt})\n        except NoSuchElementException:\n            LOG.debug("Element not found yet", kv={"attempt": attempt})\n        except StaleElementReferenceException as exc:\n            last_error = exc\n        _swipe_direction(driver, direction, element=container, distance_fraction=distance_fraction, duration_ms=500, gesture_name="scroll_to_element")\n\n    detail = f" (last error: {last_error})" if last_error else ""\n    raise ElementNotFoundError(\n        f"Element ({locator[0]}, {locator[1]!r}) not visible after {max_swipes} swipes in direction {direction!r}.{detail} "\n        f"Check the locator, the swipe direction, or increase max_swipes."\n    )\n\n\n# ---------------------------------------------------------------------------\n# drag and drop\n# ---------------------------------------------------------------------------\ndef drag_and_drop(\n    driver: Any,\n    source_element: Any,\n    target_element: Any,\n    hold_seconds: float = 1.0,\n    move_duration_ms: int = 800,\n) -> None:\n    """Drag an element onto another element.\n\n    W3C sequence: press the source centre, hold it for ``hold_seconds``\n    (Android registers a long-click-drag after ~0.5 s), glide to the target\n    centre over ``move_duration_ms`` and release.\n\n    iOS alternative (kept for reference, not used by default):\n    ``mobile: dragFromToForDuration`` requires coordinates in *points* plus a\n    duration in seconds - W3C actions accept the same geometry with pixels.\n    """\n    sx, sy = _element_center(source_element)\n    tx, ty = _element_center(target_element)\n    pointer = _new_touch("drag")\n    pointer.create_pointer_move(duration=0, x=sx, y=sy)\n    pointer.create_pointer_down(button=0)\n    pointer.create_pause(hold_seconds)\n    pointer.create_pointer_move(duration=move_duration_ms, x=tx, y=ty)\n    pointer.create_pause(0.05)\n    pointer.create_pointer_up(button=0)\n    _dispatch(\n        driver,\n        [pointer],\n        "drag_and_drop",\n        source=(sx, sy),\n        target=(tx, ty),\n        hold_s=hold_seconds,\n        move_ms=move_duration_ms,\n    )\n\n\n# ---------------------------------------------------------------------------\n# pinch / zoom (native where possible)\n# ---------------------------------------------------------------------------\ndef _w3c_pinch(driver: Any, x: int, y: int, zoom_in: bool, spread: int = 120, duration_ms: int = 400) -> None:\n    """Generic two-finger pinch with W3C actions (fallback engine)."""\n    finger_a = _new_touch("pinch_a")\n    finger_b = _new_touch("pinch_b")\n    if zoom_in:  # fingers start close together and spread apart\n        a_start, b_start, a_end, b_end = (x - 15, y), (x + 15, y), (x - spread, y), (x + spread, y)\n    else:  # fingers start apart and come together\n        a_start, b_start, a_end, b_end = (x - spread, y), (x + spread, y), (x - 15, y), (x + 15, y)\n    for pointer, (sx, sy), (ex, ey) in ((finger_a, a_start, a_end), (finger_b, b_start, b_end)):\n        pointer.create_pointer_move(duration=0, x=sx, y=sy)\n        pointer.create_pointer_down(button=0)\n        pointer.create_pointer_move(duration=duration_ms, x=ex, y=ey)\n        pointer.create_pause(0.05)\n        pointer.create_pointer_up(button=0)\n    _dispatch(driver, [finger_a, finger_b], "pinch_open" if zoom_in else "pinch_close", centre=(x, y))\n\n\ndef zoom_in(driver: Any, element: Any | None = None) -> None:\n    """Pinch OUT (spread fingers) = zoom in.\n\n    Android: ``mobile: pinchOpenGesture`` (percent of the area/element).\n    iOS: ``mobile: pinch`` with scale > 1 (XCUITest ``pinchWithScale``).\n    """\n    platform = detect_platform(driver)\n    try:\n        if platform == "android":\n            params: dict = {"percent": 0.5}\n            if element is not None:\n                params["elementId"] = element.id\n            _mobile(driver, "mobile: pinchOpenGesture", params, "zoom_in")\n        else:\n            params = {"scale": 1.5, "velocity": 1.0}\n            if element is not None:\n                params["elementId"] = element.id\n            _mobile(driver, "mobile: pinch", params, "zoom_in", scale=1.5)\n    except WebDriverException as exc:\n        LOG.warning("Native pinch open failed; using W3C fallback", kv={"reason": str(exc)[:200]})\n        x, y = _element_center(element) if element is not None else (_viewport(driver)[0] // 2, _viewport(driver)[1] // 2)\n        _w3c_pinch(driver, x, y, zoom_in=True)\n\n\ndef zoom_out(driver: Any, element: Any | None = None) -> None:\n    """Pinch IN (bring fingers together) = zoom out.\n\n    Android: ``mobile: pinchCloseGesture``; iOS: ``mobile: pinch`` with\n    scale < 1.\n    """\n    platform = detect_platform(driver)\n    try:\n        if platform == "android":\n            params: dict = {"percent": 0.5}\n            if element is not None:\n                params["elementId"] = element.id\n            _mobile(driver, "mobile: pinchCloseGesture", params, "zoom_out")\n        else:\n            params = {"scale": 0.5, "velocity": 1.0}\n            if element is not None:\n                params["elementId"] = element.id\n            _mobile(driver, "mobile: pinch", params, "zoom_out", scale=0.5)\n    except WebDriverException as exc:\n        LOG.warning("Native pinch close failed; using W3C fallback", kv={"reason": str(exc)[:200]})\n        x, y = _element_center(element) if element is not None else (_viewport(driver)[0] // 2, _viewport(driver)[1] // 2)\n        _w3c_pinch(driver, x, y, zoom_in=False)\n\n\n# ---------------------------------------------------------------------------\n# platform-level commands\n# ---------------------------------------------------------------------------\ndef back(driver: Any) -> None:\n    """Press the Android system back button.\n\n    iOS has no system back; use the application\'s own navigation controls\n    via page objects (e.g. ``nav_bar.tap_back()``).\n    """\n    if detect_platform(driver) == "android":\n        driver.back()\n        LOG.info("Gesture performed", kv={"gesture": "back_android"})\n        return\n    raise GestureNotSupportedError(\n        "back() is only available on Android. iOS applications expose their "\n        "own back/navigation buttons - interact with those through page objects."\n    )\n\n\ndef is_keyboard_shown(driver: Any) -> bool:\n    """True when the soft keyboard is currently on screen (both platforms)."""\n    try:\n        return bool(driver.is_keyboard_shown())\n    except WebDriverException as exc:\n        LOG.debug("Keyboard state unknown", kv={"reason": str(exc)[:120]})\n        return False\n\n\ndef hide_keyboard(driver: Any, strategy: str | None = None) -> None:\n    """Hide the soft keyboard if it is visible.\n\n    Android: sends the KEYCODE_BACK key event (only when the keyboard is\n    actually shown - never backgrounds the app). iOS: taps the keyboard\n    dismiss key (default strategy; pass ``strategy="pressKey"`` or\n    ``"swipeDown"`` for the XCUITest alternatives).\n\n    Never raises when the keyboard is already hidden - logs instead.\n    """\n    platform = detect_platform(driver)\n    if platform == "android" and not is_keyboard_shown(driver):\n        LOG.debug("Keyboard not shown; nothing to hide")\n        return\n    try:\n        if platform == "android":\n            driver.hide_keyboard(strategy=strategy or "keycode")\n        else:\n            driver.hide_keyboard(strategy=strategy or "default")\n        LOG.info("Gesture performed", kv={"gesture": "hide_keyboard", "platform": platform, "strategy": strategy or "default"})\n    except WebDriverException as exc:\n        LOG.warning("Failed to hide keyboard (it may already be hidden)", kv={"reason": str(exc)[:200]})\n\n\n# Backwards-friendly aliases --------------------------------------------------\ndef tap(driver: Any, x: float, y: float) -> None:\n    """Alias for :func:`tap_at`."""\n    tap_at(driver, x, y)\n\n\ndef double_tap(driver: Any, x: float | None = None, y: float | None = None, element: Any | None = None) -> None:\n    """Double tap at coordinates or on an element (see module docstring)."""\n    if element is not None:\n        double_tap_element(driver, element)\n    elif x is not None and y is not None:\n        double_tap_at(driver, x, y)\n    else:\n        raise ValueError("double_tap() needs an element or both x and y.")\n\n\ndef scroll(\n    driver: Any,\n    direction: str,\n    element: Any | None = None,\n    distance_fraction: float = 0.75,\n    duration_ms: int = 700,\n) -> None:\n    """Generic scroll in ``up|down|left|right`` (finger travel semantics)."""\n    _swipe_direction(driver, direction, element, distance_fraction, duration_ms, "scroll")\n\n\ndef flick(\n    driver: Any,\n    direction: str,\n    element: Any | None = None,\n    distance_fraction: float = 0.5,\n    duration_ms: int = 120,\n) -> None:\n    """Generic flick in ``up|down|left|right`` (finger travel semantics)."""\n    _swipe_direction(driver, direction, element, distance_fraction, duration_ms, "flick")\n'),
    ('utils/logger.py', '"""Structured logging for the framework.\n\nDesign notes\n------------\n* A single parent logger (``appium_framework``) owns two handlers:\n  a rotating file handler (``logs/suite.log``) and, optionally, a colored\n  console handler. Component loggers are children of it, so *one* call to\n  ``setup_logging()`` configures the whole suite - including the Appium\n  server manager and pytest hooks.\n* ``get_logger(name)`` returns a tiny wrapper whose methods accept\n  ``kv=...`` keyword arguments for structured key=value context, e.g.::\n\n      log = get_logger(__name__)\n      log.info(\'Driver created\', kv={\'session_id\': sid, \'platform\': \'android\'})\n\n* Timestamps are local time in ISO-8601 form, which sorts cleanly when logs\n  are diffed across machines/timezones.\n\nWhere are the logs?\n-------------------\n* ``logs/suite.log``          -> everything the framework + tests log\n* ``logs/appium_server.log``  -> stdout of the spawned Appium server process\n  (see ``utils/appium_server.py``)\nBoth directories are created automatically and are git-ignored.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport sys\nfrom pathlib import Path\n\nPARENT_NAME = "appium_framework"\n_LOG_FORMAT = "%(asctime)s | %(levelname)-8s | %(name)s | %(message)s"\n_TIMESTAMP_FORMAT = "%Y-%m-%d %H:%M:%S"\n\n# ANSI colours for terminals that support them\n_COLORS = {\n    "DEBUG": "\\033[2m",       # faint\n    "INFO": "\\033[0m",\n    "WARNING": "\\033[33m",    # yellow\n    "ERROR": "\\033[31m",      # red\n    "CRITICAL": "\\033[41m",   # red background\n}\n_RESET = "\\033[0m"\n\n\nclass _ColoredFormatter(logging.Formatter):\n    """Adds ANSI colours to the console handler when stdout is a TTY."""\n\n    def __init__(self, fmt: str, use_color: bool):\n        super().__init__(fmt=fmt, datefmt=_TIMESTAMP_FORMAT)\n        self._use_color = use_color\n\n    def format(self, record: logging.LogRecord) -> str:\n        message = super().format(record)\n        if not self._use_color:\n            return message\n        color = _COLORS.get(record.levelname, _RESET)\n        return f"{color}{message}{_RESET}"\n\n\nclass _Logger:\n    """Thin wrapper adding structured ``kv=...`` context to a child logger."""\n\n    def __init__(self, name: str):\n        self._logger = logging.getLogger(f"{PARENT_NAME}.{name}")\n        self._name = name\n\n    # -- helpers ----------------------------------------------------------\n    @staticmethod\n    def _with_kv(message: str, kv: dict | None) -> str:\n        if not kv:\n            return message\n        context = " ".join(f"{key}={value}" for key, value in kv.items())\n        return f"{message} | {context}"\n\n    # -- logging methods --------------------------------------------------\n    def debug(self, message: str, *args, kv: dict | None = None, **kwargs) -> None:\n        self._logger.debug(self._with_kv(message, kv), *args, **kwargs)\n\n    def info(self, message: str, *args, kv: dict | None = None, **kwargs) -> None:\n        self._logger.info(self._with_kv(message, kv), *args, **kwargs)\n\n    def warning(self, message: str, *args, kv: dict | None = None, **kwargs) -> None:\n        self._logger.warning(self._with_kv(message, kv), *args, **kwargs)\n\n    def error(self, message: str, *args, kv: dict | None = None, **kwargs) -> None:\n        self._logger.error(self._with_kv(message, kv), *args, **kwargs)\n\n    def exception(self, message: str, *args, kv: dict | None = None, **kwargs) -> None:\n        """Logs at ERROR level including the current exception traceback."""\n        self._logger.exception(self._with_kv(message, kv), *args, **kwargs)\n\n\ndef setup_logging(log_dir: Path, level: str = "INFO", console: bool = True) -> logging.Logger:\n    """Configure the parent logger once (idempotent).\n\n    Args:\n        log_dir: Directory for ``suite.log``; created if missing.\n        level:   Minimum level ("DEBUG" | "INFO" | "WARNING" | "ERROR").\n        console: Mirror log records to stdout (colored on TTYs).\n\n    Returns:\n        The parent ``logging.Logger``.\n    """\n    parent = logging.getLogger(PARENT_NAME)\n    if getattr(parent, "_fw_configured", False):\n        return parent\n\n    log_dir = Path(log_dir)\n    log_dir.mkdir(parents=True, exist_ok=True)\n    parent.setLevel(logging.DEBUG)  # children decide via handler level\n    level_upper = str(level).strip().upper()\n\n    # File handler: everything >= configured level, plain text\n    file_handler = logging.FileHandler(log_dir / "suite.log", encoding="utf-8")\n    file_handler.setLevel(level_upper)\n    file_handler.setFormatter(logging.Formatter(_LOG_FORMAT, datefmt=_TIMESTAMP_FORMAT))\n    parent.addHandler(file_handler)\n\n    if console:\n        console_handler = logging.StreamHandler(sys.stdout)\n        console_handler.setLevel(level_upper)\n        use_color = hasattr(sys.stdout, "isatty") and sys.stdout.isatty()\n        console_handler.setFormatter(_ColoredFormatter(_LOG_FORMAT, use_color=use_color))\n        parent.addHandler(console_handler)\n\n    parent._fw_configured = True  # type: ignore[attr-defined]\n    return parent\n\n\ndef get_logger(name: str) -> _Logger:\n    """Return a structured logger child: ``get_logger(__name__)``."""\n    return _Logger(name)\n'),
    ('utils/screenshot.py', '"""Failure-artifact capture: screenshots and page source.\n\nEvery test failure triggers ``capture_failure_artifacts`` (see\n``conftest.py``); pages can also take deliberate screenshots with\n``save_screenshot`` (e.g. at the end of a smoke test).\n\nWhere are the artifacts stored?\n-------------------------------\n* ``artifacts/screenshots/``  -> PNG screenshots, named ``<test>_<timestamp>.png``\n* ``artifacts/page_source/``  -> XML snapshots of the view hierarchy at the\n  moment of failure (invaluable for debugging locator problems)\n\nBoth locations come from ``paths`` in ``config/settings.yaml`` and are\ncreated on demand.\n"""\n\nfrom __future__ import annotations\n\nfrom datetime import datetime\nfrom pathlib import Path\n\nfrom utils.logger import get_logger\n\nLOG = get_logger("utils.screenshot")\n\n_TIMESTAMP_FORMAT = "%Y%m%d_%H%M%S_%f"\n\n\ndef _timestamp() -> str:\n    return datetime.now().strftime(_TIMESTAMP_FORMAT)\n\n\ndef _safe_name(name: str) -> str:\n    """Keep artifact filenames filesystem- and shell-friendly."""\n    return "".join(ch if ch.isalnum() or ch in "-_" else "_" for ch in name)\n\n\ndef _prepare_dir(directory: Path) -> Path:\n    directory.mkdir(parents=True, exist_ok=True)\n    return directory\n\n\ndef save_screenshot(driver, directory: Path, name: str) -> Path:\n    """Save ``driver``\'s current screen as a PNG. Returns the file path."""\n    directory = _prepare_dir(Path(directory))\n    target = directory / f"{_safe_name(name)}_{_timestamp()}.png"\n    try:\n        png = driver.get_screenshot_as_png()\n    except Exception as exc:  # driver may already be gone (e.g. session crash)\n        LOG.warning("Could not take screenshot", kv={"reason": str(exc), "target": str(target)})\n        raise\n    target.write_bytes(png)\n    LOG.info("Screenshot saved", kv={"path": str(target)})\n    return target\n\n\ndef save_page_source(driver, directory: Path, name: str) -> Path:\n    """Save the current XML view hierarchy. Returns the file path."""\n    directory = _prepare_dir(Path(directory))\n    target = directory / f"{_safe_name(name)}_{_timestamp()}.xml"\n    try:\n        source = driver.page_source\n    except Exception as exc:\n        LOG.warning("Could not capture page source", kv={"reason": str(exc)})\n        raise\n    target.write_text(source or "", encoding="utf-8")\n    LOG.info("Page source saved", kv={"path": str(target)})\n    return target\n\n\ndef capture_failure_artifacts(\n    driver,\n    name: str,\n    screenshot_dir: Path,\n    page_source_dir: Path,\n) -> dict:\n    """Best-effort capture of screenshot + page source after a failure.\n\n    Never raises: artifact capture must not mask the original test error.\n    Returns a dict of what was captured (used by pytest hooks for logging).\n    """\n    captured = {}\n    if driver is None:\n        return captured\n    # A driver whose session already ended cannot produce artifacts\n    try:\n        if not getattr(driver, "session_id", None):\n            return captured\n    except Exception:\n        return captured\n\n    for kind, saver, directory in (\n        ("screenshot", save_screenshot, screenshot_dir),\n        ("page_source", save_page_source, page_source_dir),\n    ):\n        try:\n            captured[kind] = saver(driver, directory, name)\n        except Exception as exc:\n            LOG.error(f"Failed to capture {kind}", kv={"reason": str(exc)})\n    return captured\n'),
    ('utils/waits.py', '"""Explicit-wait helpers built on Selenium\'s ``WebDriverWait``.\n\nWhy explicit waits?\n-------------------\nThe framework never relies on ``time.sleep``: tests either wait for a real\ncondition (element visible, gone, text present) or poll a custom predicate.\nThis makes suites fast (waits return the moment the condition is true) and\nstable (no magic sleep values to tune per device).\n\nError handling\n--------------\nEvery ``wait_*`` helper converts Selenium\'s ``TimeoutException`` into a\n:class:`~utils.errors.WaitTimeoutError` whose message includes the locator,\nthe timeout and a hint to inspect the failure screenshot. The original\nexception is preserved as ``__cause__`` so the stack trace stays intact.\n"""\n\nfrom __future__ import annotations\n\nimport time\nfrom typing import Callable, TypeVar\n\nfrom selenium.common.exceptions import (\n    NoSuchElementException,\n    StaleElementReferenceException,\n    TimeoutException,\n)\nfrom selenium.webdriver.remote.webelement import WebElement\nfrom selenium.webdriver.support import expected_conditions as EC\nfrom selenium.webdriver.support.wait import WebDriverWait\n\nfrom utils.errors import WaitTimeoutError\nfrom utils.logger import get_logger\n\nLOG = get_logger("utils.waits")\n\nT = TypeVar("T")\n\nDEFAULT_POLL = 0.3  # seconds between condition polls\n\n\n# ---------------------------------------------------------------------------\n# low-level: wait on a bare predicate (driver-independent)\n# ---------------------------------------------------------------------------\ndef wait_until(\n    condition: Callable[[], T],\n    timeout: float,\n    description: str = "condition",\n    poll_frequency: float = DEFAULT_POLL,\n) -> T:\n    """Poll ``condition()`` every ``poll_frequency`` s until it returns a\n    truthy value or ``timeout`` s elapse.\n\n    Unlike Selenium\'s ``WebDriverWait`` this does not swallow exceptions:\n    exceptions propagate immediately (useful when the *absence* of an\n    exception is itself the condition being awaited).\n    """\n    deadline = time.monotonic() + timeout\n    while True:\n        result = condition()\n        if result:\n            return result\n        if time.monotonic() >= deadline:\n            raise WaitTimeoutError(f"Timed out after {timeout}s waiting for {description}.")\n        time.sleep(poll_frequency)\n\n\n# ---------------------------------------------------------------------------\n# element-focused helpers (locator = (by, value) tuple, e.g. (AppiumBy.ID, "x"))\n# ---------------------------------------------------------------------------\ndef _new_wait(driver, timeout: float | None, poll_frequency: float, default: float) -> WebDriverWait:\n    effective = default if timeout is None else timeout\n    return WebDriverWait(driver, timeout=effective, poll_frequency=poll_frequency)\n\n\ndef _as_locator(by, value) -> tuple:\n    if value is None and isinstance(by, (tuple, list)) and len(by) == 2:\n        return tuple(by)\n    return (by, value)\n\n\ndef _describe(locator: tuple) -> str:\n    return f"({locator[0]}, {locator[1]!r})"\n\n\ndef wait_for_presence(\n    driver,\n    by,\n    value=None,\n    timeout: float | None = None,\n    default: float = 15,\n    poll_frequency: float = DEFAULT_POLL,\n) -> WebElement:\n    """Wait until an element exists in the (native) view hierarchy.\n\n    Use when the element may exist but is not yet tappable/visible, e.g.\n    list items that exist but are still rendering.\n    """\n    locator = _as_locator(by, value)\n    try:\n        element = _new_wait(driver, timeout, poll_frequency, default).until(\n            EC.presence_of_element_located(locator)\n        )\n    except TimeoutException as exc:\n        LOG.error("Element never became present", kv={"locator": _describe(locator), "timeout": timeout or default})\n        raise WaitTimeoutError(\n            f"Element {_describe(locator)} was not present after {timeout or default}s."\n        ) from exc\n    LOG.debug("Element present", kv={"locator": _describe(locator)})\n    return element\n\n\ndef wait_for_visibility(\n    driver,\n    by,\n    value=None,\n    timeout: float | None = None,\n    default: float = 15,\n    poll_frequency: float = DEFAULT_POLL,\n) -> WebElement:\n    """Wait until an element exists AND is visible (non-zero size, displayed).\n\n    This is the most common wait in the framework and the recommended default\n    for page objects.\n    """\n    locator = _as_locator(by, value)\n    try:\n        element = _new_wait(driver, timeout, poll_frequency, default).until(\n            EC.visibility_of_element_located(locator)\n        )\n    except TimeoutException as exc:\n        LOG.error("Element never became visible", kv={"locator": _describe(locator), "timeout": timeout or default})\n        raise WaitTimeoutError(\n            f"Element {_describe(locator)} was not visible after {timeout or default}s."\n        ) from exc\n    LOG.debug("Element visible", kv={"locator": _describe(locator)})\n    return element\n\n\ndef wait_for_invisibility(\n    driver,\n    by,\n    value=None,\n    timeout: float | None = None,\n    default: float = 15,\n    poll_frequency: float = DEFAULT_POLL,\n) -> bool:\n    """Wait until an element disappears from the hierarchy (or is not\n    visible). Returns True on success; raises :class:`WaitTimeoutError`.\n\n    Typical use: splash screens, progress spinners, dialogs closing.\n    """\n    locator = _as_locator(by, value)\n    try:\n        gone = _new_wait(driver, timeout, poll_frequency, default).until(\n            EC.invisibility_of_element_located(locator)\n        )\n    except TimeoutException as exc:\n        LOG.error("Element never disappeared", kv={"locator": _describe(locator), "timeout": timeout or default})\n        raise WaitTimeoutError(\n            f"Element {_describe(locator)} was still present after {timeout or default}s."\n        ) from exc\n    LOG.debug("Element gone", kv={"locator": _describe(locator)})\n    return bool(gone)\n\n\ndef wait_for_clickable(\n    driver,\n    by,\n    value=None,\n    timeout: float | None = None,\n    default: float = 15,\n    poll_frequency: float = DEFAULT_POLL,\n) -> WebElement:\n    """Wait until an element is visible and enabled (ready for tapping)."""\n    locator = _as_locator(by, value)\n    try:\n        element = _new_wait(driver, timeout, poll_frequency, default).until(\n            EC.element_to_be_clickable(locator)\n        )\n    except TimeoutException as exc:\n        LOG.error("Element never became clickable", kv={"locator": _describe(locator), "timeout": timeout or default})\n        raise WaitTimeoutError(\n            f"Element {_describe(locator)} was not clickable after {timeout or default}s."\n        ) from exc\n    return element\n\n\ndef wait_for_text(\n    driver,\n    by,\n    value,\n    expected_text: str,\n    timeout: float | None = None,\n    default: float = 15,\n    poll_frequency: float = DEFAULT_POLL,\n) -> bool:\n    """Wait until the element\'s text attribute contains ``expected_text``."""\n    locator = _as_locator(by, value)\n    try:\n        found = _new_wait(driver, timeout, poll_frequency, default).until(\n            EC.text_to_be_present_in_element(locator, expected_text)\n        )\n    except TimeoutException as exc:\n        LOG.error(\n            "Element text never matched",\n            kv={"locator": _describe(locator), "expected": expected_text, "timeout": timeout or default},\n        )\n        raise WaitTimeoutError(\n            f"Text {expected_text!r} was not found in {_describe(locator)} "\n            f"after {timeout or default}s."\n        ) from exc\n    return bool(found)\n\n\n# ---------------------------------------------------------------------------\n# non-blocking existence checks (single, immediate lookups)\n# ---------------------------------------------------------------------------\ndef is_element_present(driver, by, value=None, attempts: int = 1) -> bool:\n    """Return True if the element exists right now.\n\n    With an implicit wait of 0 the driver performs a single lookup, so this\n    is fast and safe to call in loops.\n    """\n    locator = _as_locator(by, value)\n    for _ in range(max(1, attempts)):\n        try:\n            driver.find_element(*locator)\n            return True\n        except NoSuchElementException:\n            continue\n        except StaleElementReferenceException:\n            continue\n    return False\n\n\ndef is_element_visible(driver, by, value=None, attempts: int = 1) -> bool:\n    """Return True if the element exists and is currently displayed."""\n    locator = _as_locator(by, value)\n    for _ in range(max(1, attempts)):\n        try:\n            return bool(driver.find_element(*locator).is_displayed())\n        except (NoSuchElementException, StaleElementReferenceException):\n            continue\n    return False\n'),
]


# ---------------------------------------------------------------------------
def _write_file(target_dir: Path, relative_path: str, content: str, force: bool) -> str:
    target = target_dir / relative_path
    if target.exists() and not force:
        return "skip"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")
    return "create"


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description="Scaffold the Appium Python mobile test framework.")
    parser.add_argument("--target", default=".", help="Directory to create the project in (default: current directory)")
    parser.add_argument("--force", "-f", action="store_true", help="Overwrite files that already exist")
    parser.add_argument("--dry-run", action="store_true", help="Only print what would be done")
    args = parser.parse_args(argv)

    target_dir = Path(args.target).resolve()
    created, skipped, errors = [], [], []

    print(f"create_framework.py: {'[DRY RUN] would create' if args.dry_run else 'creating'} "
          f"{len(FILES)} files under {target_dir}\n")

    for relative_path, content in FILES:
        try:
            if args.dry_run:
                status = "create" if not (target_dir / relative_path).exists() else "skip"
            else:
                status = _write_file(target_dir, relative_path, content, args.force)
        except OSError as exc:
            errors.append((relative_path, str(exc)))
            print(f"[error] {relative_path}: {exc}")
            continue

        if status == "create":
            created.append(relative_path)
            print(f"[create] {relative_path}")
        else:
            skipped.append(relative_path)
            print(f"[skip]   {relative_path} (exists - use --force to overwrite)")

    print("\n" + "=" * 70)
    print(f"Summary: {len(created)} created, {len(skipped)} skipped (existing), {len(errors)} errors")
    if created and not args.dry_run:
        print("\nNext steps:")
        print(f"  cd {target_dir}")
        print("  python -m pip install -r requirements.txt")
        print("  # edit config/android.yaml + config/ios.yaml: device name, app path")
        print("  python run_tests.py --platform android")
        print("  python run_tests.py --platform ios")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
